insert into public.exercises (name_ar, name_en, muscle_group, equipment, instructions_ar, instructions_en, video_url, steps_ar, steps_en, primary_muscles, secondary_muscles, difficulty) values
  ('البلانك (تمرين اللوح)', 'Plank', 'core', 'none', 'استلق على وجهك على سجادة تمرين مع وضع مرفقيك بجانبيك وراحتا يديك مسطحتان على الأرض. مع شد جذعك ومقعدتك، ارفع جسمك عن الأرض مرتكزًا على ساعديك وأطراف أصابع قدميك. حافظ على وضعية البلانك مع التنفس بحرية وشد المقعدة.', 'Lie face down on a mat with your elbows to your sides, palms flat on the floor. Engaging your core and glutes, raise your body from the floor, supporting your weight on your forearms and toes. Hold the plank position while breathing freely, keeping glutes tensed.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/plank.gif', ARRAY['استلق على وجهك على سجادة تمرين مع وضع مرفقيك بجانبيك، ورأسك متجهًا للأمام، وراحتا يديك مسطحتان على الأرض.','مع شد جذعك ومقعدتك، ارفع جسمك عن الأرض، مرتكزًا بوزنك على ساعديك وأطراف أصابع قدميك مع التنفس بحرية.','حافظ على وضعية البلانك مع الحفاظ على الأداء الصحيح وشد المقعدة، ثم عد إلى وضع البداية ببطء وبتحكم جيد.'], ARRAY['Lie face down on an exercise mat with your elbows to your sides, your head facing forward, and palms flat on the floor.','Engaging your core and glutes, raise your body from the floor, supporting your weight on your forearms and toes while breathing freely.','Hold the plank position, maintaining good form and keeping your glutes tensed, then return to the start position slowly and with good control.'], ARRAY['rectus abdominis'], ARRAY['obliques','iliopsoas','quadriceps','tensor fasciae latae','sartorius','pectoralis major','serratus anterior','erector spinae','trapezius','rhomboids'], 'beginner'),
  ('البلانك العالي', 'High Plank', 'core', 'none', 'ابدأ في وضعية الضغط، بيديك مباشرة تحت كتفيك ورجليك مفرودتين خلفك. شد جذعك واضغط بمقعدتك، وحافظ على جسمك في خط مستقيم من الرأس إلى الكعبين. حافظ على الوضعية مع التنفس بثبات، وتجنب تدلي الجسم أو تقوسه. ابدأ بمدة 20-30 ثانية وزدها تدريجيًا.', 'Start in a push-up position, hands directly under the shoulders, legs extended behind you. Engage your core, squeeze your glutes, and keep your body in a straight line from head to heels. Hold the position while breathing steadily, avoiding sagging or arching. Begin with 20-30 seconds, increasing over time.', 'https://fitnessprogramer.com/wp-content/uploads/2023/07/High-Plank.gif', ARRAY['ابدأ في وضعية الضغط، بيديك مباشرة تحت كتفيك ورجليك مفرودتين خلفك.','شد جذعك واضغط بمقعدتك، وحافظ على جسمك في خط مستقيم من الرأس إلى الكعبين.','اضغط بقوة عبر يديك، مع الحفاظ على كتفيك نشطتين وثابتتين.','حافظ على الوضعية مع التنفس بثبات، وتجنب تدلي الجسم أو تقوسه.','ابدأ بمدة 20-30 ثانية، وزد المدة تدريجيًا مع تحسن قوتك.'], ARRAY['Start in a push-up position, with hands directly under the shoulders and legs extended behind you.','Engage your core, squeeze your glutes, and keep your body in a straight line from head to heels.','Press firmly through the hands, keeping your shoulders active and stable.','Hold the position while breathing steadily, avoiding any sagging or arching.','Begin with 20-30 seconds, gradually increasing time as strength improves.'], ARRAY['rectus abdominis','transverse abdominis','obliques','deltoids','triceps brachii'], ARRAY['trapezius','quadriceps','glutes','erector spinae'], 'beginner'),
  ('علم التنين', 'Dragon Flag', 'core', 'none', 'استلق على ظهرك بشكل مسطح على بنش ثابت، مع دعم رأسك ووضع يديك بثبات على البنش فوق رأسك. ارفع رجليك ووركيك عن البنش مع الحفاظ على استقامتهما في خط واحد من الرأس إلى القدمين. أنزلهما ببطء نحو البنش مع الحفاظ على خط الجسم المستقيم، ثم اعكس الحركة باستخدام قوة الجذع للعودة للأعلى. هذا تمرين متقدم يتطلب عضلات جذع قوية وغير مناسب للمبتدئين.', 'Lie flat on your back on a sturdy bench, head supported, hands firmly on the bench above your head. Lift your legs and hips off the bench, keeping them straight in one line from head to feet. Slowly lower toward the bench maintaining the straight line, then reverse using core strength to raise back up. This is a challenging exercise requiring strong core muscles, not recommended for beginners.', 'https://fitnessprogramer.com/wp-content/uploads/2022/07/Leg-Raise-Dragon-Flag.gif', ARRAY['استلق على ظهرك بشكل مسطح على بنش ثابت أو سطح مستوٍ. تأكد من دعم رأسك وضع يديك بثبات على البنش أو أمسك سطحًا ثابتًا فوق رأسك.','ارفع رجليك ووركيك عن البنش، مع الحفاظ على استقامتهما بحيث يشكل جسمك خطًا مستقيمًا من الرأس إلى القدمين.','أنزل رجليك ووركيك ببطء نحو البنش مع الحفاظ على خط الجسم المستقيم، مع التركيز على التحكم بعضلات البطن.','اعكس الحركة باستخدام قوة الجذع لرفع رجليك ووركيك مرة أخرى إلى وضع البداية.','نفّذ العدد المطلوب من التكرارات.'], ARRAY['Lie flat on your back on a sturdy bench or flat surface. Ensure your head is supported and place your hands firmly on the bench or hold onto a stable surface above your head.','Lift your legs and hips off the bench, keeping them straight so your body forms a straight line from head to feet.','Slowly lower your legs and hips towards the bench while maintaining a straight body line, focusing on abdominal control.','Reverse the movement by using core strength to raise your legs and hips back to starting position.','Perform for your desired number of repetitions.'], ARRAY['rectus abdominis'], ARRAY['obliques','erector spinae','latissimus dorsi','hip flexors','glutes','adductors'], 'advanced'),
  ('تجعيد الذراع بالبار', 'Barbell Curl', 'arms', 'barbell', 'قف بشكل مستقيم وقدماك بعرض الكتفين، وأمسك البار بقبضة سفلية. حافظ على مرفقيك قريبين من جانبيك وارفع البار نحو صدرك مع تقلص عضلات البايسبس. أنزل البار ببطء إلى وضع البداية، مع الحفاظ على شد البايسبس طوال الحركة.', 'Stand up straight with feet shoulder-width apart and grasp the barbell with an underhand grip. Keep your elbows close to your sides and lift the barbell towards your chest while contracting your biceps. Slowly lower the barbell back to the starting position, keeping your biceps engaged throughout.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Barbell-Curl.gif', ARRAY['قف بشكل مستقيم وقدماك بعرض الكتفين، وأمسك البار بقبضة سفلية (راحتا يديك للأعلى).','حافظ على مرفقيك قريبين من جانبيك وارفع البار نحو صدرك مع تقلص عضلات البايسبس.','أنزل البار ببطء إلى وضع البداية، مع الحفاظ على شد البايسبس طوال الحركة.','نفّذ العدد المطلوب من التكرارات.'], ARRAY['Stand up straight with your feet shoulder-width apart and grasp the barbell with an underhand grip.','Keep your elbows close to your sides and lift the barbell towards your chest, while contracting your biceps.','Slowly lower the barbell back to the starting position, keeping your biceps engaged throughout.','Perform desired repetitions.'], ARRAY['biceps'], ARRAY['brachialis','brachioradialis','wrist flexors'], NULL),
  ('تجعيد الذراع بالدمبل', 'Dumbbell Curl', 'arms', 'dumbbell', 'قف بشكل مستقيم وقدماك بعرض الكتفين وكتفاك للخلف. أمسك الدمبل بقبضة محايدة مع استقامة معصميك. حافظ على مرفقيك قريبين من جانبيك. اثنِ ذراعًا واحدة في كل مرة نحو كتفك، ثم أنزلها بشكل متحكم. بدّل بين الذراعين.', 'Stand up straight with feet shoulder-width apart, shoulders back. Hold the dumbbells with a neutral grip, wrists straight. Keep your elbows close to your sides. Curl one arm at a time toward your shoulder, then lower in a controlled manner. Alternate between arms.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Dumbbell-Curl.gif', ARRAY['قف بشكل مستقيم وقدماك بعرض الكتفين وكتفاك للخلف.','أمسك الدمبل بقبضة محايدة (راحتا يديك متجهتان للداخل) مع الحفاظ على استقامة معصميك.','حافظ على مرفقيك قريبين من جانبيك طوال الحركة.','اثنِ ذراعًا واحدة في كل مرة نحو كتفك مع تثبيت وضع مرفقك.','أنزل الوزن بشكل متحكم دون إسقاطه بسرعة.','بدّل بين الذراعين بعد إكمال تكرار كامل.','اشهق وأنت تنزل الوزن وازفر وأنت تثني ذراعك.'], ARRAY['Stand up straight with your feet shoulder-width apart and your shoulders back.','Hold the dumbbells with a neutral grip (palms facing inward) and keep your wrists straight.','Keep your elbows close to your sides throughout the movement.','Curl one arm at a time toward your shoulder while maintaining elbow position.','Lower the weight in a controlled manner without dropping quickly.','Alternate between arms after completing one full repetition.','Inhale as you lower the weight and exhale as you curl.'], ARRAY['biceps'], ARRAY['brachialis','brachioradialis','wrist flexors'], NULL),
  ('تجعيد الذراع المركّز', 'Concentration Curl', 'arms', 'dumbbell', 'اجلس على بنش وقدماك مسطحتان على الأرض، وبيدك دمبل واحد. ضع مرفقك على الجانب الداخلي لفخذك مع فرد ذراعك بالكامل. اثنِ الوزن للأعلى نحو كتفك مع تثبيت مرفقك. توقف في الأعلى، ثم أنزل ببطء. كرر ثم بدّل الذراع.', 'Sit on a bench with feet flat on the ground, a dumbbell in one hand. Place elbow on the inside of your thigh with arm fully extended. Curl the weight up towards your shoulder, keeping elbow stationary. Pause at the top, then slowly lower back down. Repeat, then switch arms.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Concentration-Curl.gif', ARRAY['اجلس على بنش أو كرسي وقدماك مسطحتان على الأرض، وبيدك دمبل واحد.','ضع مرفقك على الجانب الداخلي لفخذك، مع فرد ذراعك بالكامل وترك الدمبل يتدلى للأسفل مباشرة.','اثنِ الوزن للأعلى نحو كتفك مع تثبيت مرفقك والضغط بالجزء العلوي من ذراعك على فخذك.','توقف في أعلى الحركة، ثم أنزل الوزن ببطء إلى وضع البداية.','كرر للعدد المطلوب من التكرارات، ثم بدّل إلى الذراع الأخرى وكرر.'], ARRAY['Sit on a bench or chair with feet flat on the ground and a dumbbell in one hand.','Place elbow on the inside of your thigh, with arm fully extended and dumbbell hanging straight down.','Curl the weight up towards your shoulder, keeping elbow stationary and upper arm pressed against thigh.','Pause at the top of the movement, then slowly lower the weight back down to the starting position.','Repeat for the desired number of repetitions, then switch to the other arm and repeat.'], ARRAY['biceps'], ARRAY['brachialis','brachioradialis','wrist flexors'], NULL),
  ('تجعيد الذراع على مقعد الوعظ بالبار المضلع', 'EZ Bar Preacher Curl', 'arms', 'barbell', 'اضبط مقعد الوعظ بحيث ترتكز أعلى ذراعيك على الوسادة المائلة، مع ملامسة صدرك للوسادة. أمسك البار بقبضة سفلية مع تقريب يديك أكثر من عرض الكتفين قليلًا. مع تثبيت أعلى ذراعيك، ازفر واثنِ البار نحو صدرك، وحافظ على الانقباض في القمة. اشهق وأنزل البار ببطء إلى وضع البداية.', 'Adjust the preacher bench so upper arms rest on the angled pad, chest in contact with the pad. Grasp the EZ-bar with an underhand grip, hands slightly closer than shoulder-width. Keeping upper arms stationary, exhale and curl the bar towards your chest, holding the peak contraction. Inhale and slowly lower back to the starting position.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Z-Bar-Preacher-Curl.gif', ARRAY['اضبط مقعد الوعظ بحيث ترتكز أعلى ذراعيك بشكل مريح على الوسادة المائلة، مع تأكد من ملامسة صدرك للوسادة.','اختر وزنًا مناسبًا على البار المضلع يشكل تحديًا لعضلات البايسبس مع السماح بالحفاظ على الأداء الصحيح.','أمسك البار بقبضة سفلية (راحتا يديك للأعلى) مع تقريب يديك أكثر من عرض الكتفين قليلًا.','ضع ذراعيك على الوسادة المائلة، بحيث تكون أعلى ذراعيك عموديتين على الأرض ومرفقاك مثنيان قليلًا.','مع تثبيت أعلى ذراعيك، ازفر واثنِ البار نحو صدرك مع التركيز على تقلص البايسبس. حافظ على الانقباض في القمة لثانية.','اشهق وأنزل البار ببطء إلى وضع البداية، مع الحفاظ على التحكم والشد على البايسبس.'], ARRAY['Adjust the preacher bench so that the upper arms rest comfortably on the angled pad. Ensure that your chest is in contact with the pad.','Select a suitable weight on the EZ-bar that challenges your biceps but allows you to maintain proper form.','Grasp the EZ-bar with an underhand grip (palms facing up) with your hands slightly closer than shoulder-width apart.','Position your arms on the angled pad, with your upper arms perpendicular to the ground and your elbows slightly flexed.','Keeping your upper arms stationary, exhale and curl the bar towards your chest, focusing on contracting your biceps. Hold the peak contraction for a second.','Inhale and slowly lower the bar back to the starting position, maintaining control and tension on your biceps.'], ARRAY['biceps','brachialis'], ARRAY['brachioradialis','wrist flexors'], NULL),
  ('دفع الترايسبس بالكابل للأسفل', 'Triceps Push-down', 'arms', 'cable', 'ثبّت بارًا مستقيمًا أو حبلًا على البكرة العلوية. قف وقدماك بعرض الكتفين، وأمسك المقبض بقبضة علوية ومرفقاك قريبان من جذعك ومثنيان بزاوية 90 درجة. ازفر وأنت تدفع البار للأسفل بفرد مرفقيك بالكامل. توقف لحظة في الأسفل. اشهق وعد ببطء إلى وضع البداية.', 'Attach a straight bar, rope, or V-bar to the high pulley. Stand with feet shoulder-width apart, grip with an overhand grip, elbows close to your torso bent at 90 degrees. Exhale as you push the bar down by extending your elbows fully. Pause briefly at the bottom. Inhale and slowly return to the starting position.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Pushdown.gif', ARRAY['ثبّت بارًا مستقيمًا أو حبلًا أو مقبض V على البكرة العلوية لجهاز الكابل. اختر وزنًا متوسطًا يسمح بحركة متحكم بها.','قف وقدماك بعرض الكتفين للثبات. أمسك المقبض بقبضة علوية (راحتا يديك للأسفل). حافظ على مرفقيك قريبين من جذعك ومثنيين بزاوية 90 درجة.','ازفر وأنت تدفع البار للأسفل بفرد مرفقيك بالكامل. حافظ على معصميك في وضع محايد ومرفقيك ثابتين. أنزل المقبض حتى تصبح ذراعاك مفرودتين تمامًا دون قفل. توقف لحظة في الأسفل لتحقيق أقصى تفعيل للترايسبس.','اشهق وأنت تعود ببطء إلى وضع البداية بتحكم.','نفّذ العدد المطلوب من التكرارات مع الحفاظ على الأداء الصحيح.'], ARRAY['Attach a straight bar, rope, or V-bar to the high pulley of a cable machine. Select a moderate weight that allows for controlled movement.','Stand with feet shoulder-width apart for stability. Grip the attachment with an overhand grip (palms facing down). Keep your elbows close to your torso and bend them at a 90-degree angle.','Exhale as you push the bar down by extending your elbows fully. Keep your wrists neutral and your elbows stationary. Lower the handle until your arms are fully extended but not locked out. Pause briefly at the bottom to maximize triceps engagement.','Inhale as you slowly return to the starting position with control.','Perform the desired number of repetitions while maintaining proper form.'], ARRAY['triceps'], ARRAY[]::text[], NULL),
  ('غطس الترايسبس', 'Triceps Dips', 'arms', 'none', 'أمسك المتوازي بعرض أوسع قليلًا من الكتفين. فرد ذراعيك بالكامل وارفع جسمك. اشهق وأنت تنزل جسمك بثني مرفقيك حتى تصبح أعلى ذراعيك موازية للأرض مع إبقاء مرفقيك قريبين من جذعك. توقف لحظة في الأسفل، ثم ازفر وأنت تدفع للعودة إلى وضع البداية.', 'Grip the parallel bars slightly wider than shoulder-width. Fully extend your arms and support your body weight. Inhale as you lower your body by bending your elbows until upper arms are parallel to the ground, elbows close to your torso. Pause briefly at the bottom, then exhale as you press back up to the starting position.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Triceps-Dips.gif', ARRAY['أمسك المتوازي بيديك بعرض أوسع قليلًا من الكتفين. فرد ذراعيك بالكامل وارفع جسمك فوق المتوازي.','حافظ على صدرك متجهًا للأمام قليلًا وشد جذعك. اثنِ ركبتيك أو مدّ رجليك حسب الراحة ومستوى الصعوبة.','اشهق وأنت تنزل جسمك بثني مرفقيك حتى تصبح أعلى ذراعيك موازية للأرض. حافظ على مرفقيك قريبين من جذعك.','توقف لحظة في الأسفل لضمان تفعيل كامل للترايسبس. ازفر وأنت تدفع بكفيك لفرد ذراعيك والعودة إلى وضع البداية.','نفّذ العدد المطلوب من التكرارات مع الحفاظ على الأداء الصحيح.'], ARRAY['Grip the parallel bars with your hands slightly wider than shoulder-width apart. Fully extend your arms and support your body weight above the bars.','Keep your chest slightly forward and engage your core. Bend your knees or extend your legs straight, depending on comfort and difficulty level.','Inhale as you lower your body by bending your elbows until your upper arms are parallel to the ground. Keep your elbows close to your torso.','Pause briefly at the bottom, ensuring full triceps engagement. Exhale as you press through your palms to extend your arms and return to starting position.','Perform the desired number of repetitions while maintaining proper form.'], ARRAY['triceps'], ARRAY['anterior deltoid','pectoralis major sternal','pectoralis major clavicular','pectoralis minor','rhomboids','levator scapulae','latissimus dorsi','biceps brachii','trapezius lower'], NULL),
  ('العقلة (شد الجسم للأعلى)', 'Pull-Up', 'back', 'none', 'أمسك عقلة الحديد بعرض الكتفين وراحتا يديك متجهتان للخارج. تدلَّ بذراعين مفرودتين تمامًا. شد جذعك وظهرك، واسحب صدرك نحو العقلة مع دفع مرفقيك للأسفل وضم لوحي كتفك معًا. توقف لحظة في الأعلى بحيث تكون ذقنك أعلى من العقلة. أنزل جسمك ببطء وبتحكم.', 'Grip a pull-up bar shoulder-width apart, palms facing away. Hang with arms fully extended. Engage your core and back, pull your chest toward the bar, driving elbows downward and squeezing shoulder blades together. Pause briefly at the top with chin above the bar. Lower yourself slowly with control.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Pull-up.gif', ARRAY['أمسك عقلة الحديد بيديك بعرض الكتفين وراحتا يديك متجهتان للخارج.','تدلَّ من العقلة بذراعين مفرودتين تمامًا، ورجلاك مفرودتان أو مثنيتان قليلًا.','شد جذعك وظهرك، ثم اسحب صدرك نحو العقلة.','ادفع مرفقيك للأسفل مع ضم لوحي كتفك معًا.','توقف لحظة في الأعلى بحيث تكون ذقنك أعلى من العقلة.','أنزل جسمك ببطء وبتحكم إلى وضع البداية.'], ARRAY['Grip a pull-up bar with your hands shoulder-width apart, palms facing away.','Hang from the bar with arms fully extended, legs straight or slightly bent.','Engage your core and back, then pull your chest toward the bar.','Drive elbows downward, squeezing your shoulder blades together.','Pause briefly at the top, with chin above the bar.','Lower yourself slowly and with control to the starting position.'], ARRAY['back','lats'], ARRAY['infraspinatus','teres minor','posterior deltoid','trapezius','rhomboids','levator scapulae','teres major','biceps brachii','brachioradialis','brachialis'], NULL),
  ('سحب أمامي للأسفل', 'Lat Pulldown', 'back', 'cable', 'ثبّت مقبضًا عريضًا على الكابل. اجلس على جهاز السحب الأمامي مع تثبيت قدميك وفخذيك موازيين للأرض. أمسك المقبض وراحتا يديك متجهتان للخارج بقبضة أوسع من عرض الكتفين. اسحب المقبض للأسفل نحو صدرك بتقلص عضلات ظهرك، مع إبقاء مرفقيك قريبين من جسمك. توقف عند وصول المقبض لصدرك، ثم حرره ببطء إلى وضع البداية.', 'Attach a wide handle bar to the cable. Sit on the lat pulldown machine with feet flat and thighs parallel to ground. Grab the bar with palms facing away, grip wider than shoulder-width. Pull the bar down toward chest by contracting back muscles, keeping elbows close to body. Pause when bar reaches chest, then slowly release back to starting position.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Lat-Pulldown.gif', ARRAY['ثبّت مقبضًا عريضًا على الكابل.','اجلس على جهاز السحب الأمامي مع تثبيت قدميك ووضع ركبتيك تحت الوسادة، وفخذاك موازيان للأرض.','أمسك المقبض بكلتا يديك، وراحتا يديك متجهتان للخارج، بقبضة أوسع من عرض الكتفين.','اسحب المقبض للأسفل نحو صدرك عن طريق تقلص عضلات ظهرك، مع الحفاظ على مرفقيك متجهين للأسفل وقريبين من جسمك.','توقف لثانية واحدة عندما يصل المقبض إلى صدرك.','حرر المقبض ببطء إلى وضع البداية مع فرد ذراعيك بالكامل.','كرر للعدد المطلوب من التكرارات.'], ARRAY['Attach a wide handle bar to the cable.','Sit on the lat pulldown machine with feet flat, knees pressed against pad, thighs parallel to ground.','Grab the bar with both hands, palms facing away, grip wider than shoulder-width.','Pull the bar down toward chest by contracting back muscles, keeping elbows pointing downward and close to body.','Pause for one second when bar reaches chest.','Slowly release bar back to starting position, extending arms fully.','Repeat for desired number of reps.'], ARRAY['latissimus dorsi'], ARRAY['levator scapulae','infraspinatus','teres minor','posterior deltoid','trapezius','teres major','rhomboids','biceps brachii','brachioradialis','brachialis'], NULL),
  ('السحب بالكابل جلوسًا', 'Seated Cable Row', 'back', 'cable', 'ضع قدميك بثبات على مسند جهاز الكابل. حافظ على استقامة ظهرك مع شد جذعك. اسحب لوحي كتفك للخلف وحافظ على هذا الوضع طوال الحركة. اسحب مقابض الكابل نحوك مع فتح مرفقيك للجانبين والضغط بلوحي كتفك معًا. توقف في أعلى الحركة ثم حرر ببطء إلى وضع البداية.', 'Place your feet firmly on the footrest of the cable machine. Keep your back straight, engaging your core. Retract your shoulder blades and keep them in this position throughout. Pull the cable handles towards you with elbows flared out, squeezing your shoulder blades together. Pause at the top, then slowly release back to the starting position.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Seated-Cable-Row.gif', ARRAY['ضع قدميك بثبات على المسند أو المنصة الخاصة بجهاز الكابل.','حافظ على استقامة ظهرك وتجنب الانحناء أو تقويس كتفيك للأمام. شد عضلات جذعك.','قبل بدء التمرين، اسحب لوحي كتفك للخلف وحافظ على هذا الوضع طوال الحركة.','بينما تسحب مقابض الكابل نحوك، حافظ على فتح مرفقيك للجانبين واضغط بلوحي كتفك معًا.','توقف لثانية في أعلى الحركة ثم حرر ببطء إلى وضع البداية.','كرر للعدد المطلوب من التكرارات.'], ARRAY['Place your feet firmly on the footrest or platform provided by the cable machine.','Keep your back straight and avoid slouching or rounding your shoulders forward. Engage your core muscles.','Before starting the exercise, retract your shoulder blades and keep them in this position throughout the movement.','As you pull the cable handles towards you, keep your elbows flared out to the sides and squeeze your shoulder blades together.','Pause for a second at the top of the movement and then slowly release back to the starting position.','Repeat for the desired number of repetitions.'], ARRAY['latissimus dorsi'], ARRAY['levator scapulae','erector spinae','infraspinatus','teres minor','posterior deltoid','trapezius','teres major','rhomboids','brachioradialis','brachialis'], NULL),
  ('التجديف بالبار منحنيًا', 'Barbell Bent Over Row', 'back', 'barbell', 'قف وقدماك بعرض الكتفين، والبار على الأرض أمامك. انحنِ من الوركين مع الحفاظ على استقامة ظهرك حتى يصبح جذعك موازيًا للأرض تقريبًا. أمسك البار بقبضة أوسع قليلًا من عرض الكتفين. اسحب البار نحو أعلى بطنك مع إبقاء مرفقيك قريبين من جسمك. أنزل البار ببطء إلى وضع البداية بتحكم.', 'Stand with feet shoulder-width apart, barbell on floor in front. Hinge at your hips keeping your back straight until torso is almost parallel to the floor. Grip the barbell slightly wider than shoulder-width. Pull the barbell towards your upper abdomen, keeping elbows close to your body. Slowly lower the barbell back down with control.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Barbell-Bent-Over-Row.gif', ARRAY['قف وقدماك بعرض الكتفين، وأصابع قدميك متجهة للأمام، والبار على الأرض أمامك.','انحنِ من الوركين مع الحفاظ على استقامة ظهرك، حتى يصبح جذعك موازيًا للأرض تقريبًا.','أمسك البار بقبضة أوسع قليلًا من عرض الكتفين وذراعاك مفرودتان تمامًا.','يجب أن يكون ظهرك مستقيمًا وصدرك بارزًا ولوحا كتفك مسحوبين للخلف والأسفل.','اسحب البار نحو أعلى بطنك أو أسفل صدرك مع الحفاظ على مرفقيك قريبين من جسمك.','أنزل البار ببطء إلى وضع البداية مع الحفاظ على التحكم.'], ARRAY['Stand with feet shoulder-width apart, toes forward, barbell on floor in front.','Hinge at your hips while keeping your back straight. Lower your torso until it is almost parallel to the floor.','Grip the barbell slightly wider than shoulder-width with fully extended arms.','Your back should be flat, chest out, and shoulder blades pulled back and down.','Pull the barbell towards your upper abdomen or lower chest while keeping your elbows close to your body.','Slowly lower the barbell back down to the starting position while maintaining control.'], ARRAY['back','erector spinae'], ARRAY['latissimus dorsi','infraspinatus','teres minor','posterior deltoid','trapezius','rhomboids','brachialis','brachioradialis','pectoralis major'], NULL),
  ('التجديف بالدمبل', 'Dumbbell Row', 'back', 'dumbbell', 'ضع ركبتك اليسرى ويدك اليسرى على بنش، مع استقامة ظهرك وجذعك موازيًا للأرض. أمسك دمبل بيدك اليمنى مع فرد ذراعك بالكامل وراحة يدك متجهة للداخل. شد جذعك واسحب الدمبل للأعلى مع توجيه مرفقك نحو وركك. توقف في الأعلى مع الضغط بلوح كتفك نحو عمودك الفقري. أنزل ببطء بتحكم ثم بدّل الجانبين.', 'Place your left knee and left hand on a bench, keeping your back flat and torso parallel to the ground. Hold a dumbbell in your right hand, arm fully extended, palm facing in. Engage your core and pull the dumbbell up, driving your elbow toward your hip. Pause at the top, squeezing your shoulder blade toward your spine. Lower slowly with control, then switch sides.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Dumbbell-Row.gif', ARRAY['ضع ركبتك اليسرى ويدك اليسرى على بنش، مع الحفاظ على استقامة ظهرك وجذعك موازيًا للأرض.','أمسك دمبل بيدك اليمنى، مع فرد ذراعك بالكامل نحو الأرض وراحة يدك متجهة للداخل.','شد جذعك واسحب الدمبل للأعلى، مع توجيه مرفقك نحو وركك.','توقف في الأعلى مع الضغط بلوح كتفك نحو عمودك الفقري.','أنزل الدمبل ببطء إلى وضع البداية بتحكم.','أكمل التكرارات ثم بدّل الجانبين.'], ARRAY['Place your left knee and left hand on a bench, keeping your back flat and torso parallel to the ground.','Hold a dumbbell in your right hand, arm fully extended toward the floor, palm facing in.','Engage your core and pull the dumbbell up, driving your elbow toward your hip.','Pause at the top, squeezing your shoulder blade toward your spine.','Lower the dumbbell slowly to the starting position under control.','Complete reps, then switch sides.'], ARRAY['latissimus dorsi'], ARRAY['trapezius middle','trapezius lower','rhomboids','teres major','posterior deltoid','infraspinatus','teres minor','brachialis','brachioradialis','pectoralis major sternal'], NULL),
  ('تجديف تي بار بالرافعة', 'Lever T-Bar Row', 'back', 'machine', 'قف مترجلًا على جهاز تجديف تي بار وأمسك المقابض. انحنِ للأمام من الوركين مع استقامة ظهرك وصدرك مرفوعًا. اسحب المقابض نحو جذعك مع دفع مرفقيك للخلف والضغط بلوحي كتفك معًا. توقف لحظة، ثم أنزل ببطء بتحكم. يستهدف هذا التمرين سلسلة عضلات الظهر بالكامل.', 'Straddle the T-bar row machine and grip the handles. Hinge forward at the hips, keeping your back flat and chest up. Pull the handles toward your torso, driving elbows back and squeezing shoulder blades together. Pause briefly, then slowly lower back with control. This exercise leverages mechanics to target the entire back chain.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Lever-T-bar-Row.gif', ARRAY['قف مترجلًا على جهاز تجديف تي بار وأمسك المقابض بكلتا يديك.','انحنِ للأمام من الوركين مع الحفاظ على استقامة ظهرك وصدرك مرفوعًا.','اسحب المقابض للأعلى نحو جذعك عن طريق دفع مرفقيك للخلف والضغط بلوحي كتفك معًا.','توقف لحظة في الأعلى، ثم أنزل ببطء إلى وضع البداية بتحكم.'], ARRAY['Straddle the T-bar row machine and grip the handles with both hands.','Hinge forward at the hips, keeping your back flat and chest up.','Pull the handles up toward your torso by driving your elbows back and squeezing your shoulder blades together.','Pause briefly at the top, then slowly lower back to the starting position with control.'], ARRAY['back','lats'], ARRAY['levator scapulae','erector spinae','infraspinatus','teres minor','posterior deltoid','trapezius','teres major','rhomboids','brachialis','brachioradialis'], NULL),
  ('رفع الكعب وقوفًا بوزن الجسم', 'Bodyweight Standing Calf Raise', 'legs', 'none', 'قف بشكل مستقيم وقدماك بعرض الوركين مع وضعية جيدة. ضع أصابع قدميك بشكل مسطح على حافة منصة مرتفعة. ارتفع ببطء على مقدمة قدميك، رافعًا كعبيك بأقصى ما يمكن، مع تقلص عضلات الساق بالكامل. أنزل كعبيك بلطف مع الحفاظ على التحكم. نفّذ 15-25 تكرارًا لكل مجموعة.', 'Stand upright with feet hip-width apart, good posture. Place your toes flat on the end of a high platform. Slowly rise onto the balls of your feet, lifting heels as high as possible, contracting the calves fully. Gently lower your heels back down with control. Perform 15-25 repetitions per set.', 'https://fitnessprogramer.com/wp-content/uploads/2021/06/Standing-Calf-Raise.gif', ARRAY['قف بشكل مستقيم وقدماك بعرض الوركين، مع الحفاظ على وضعية جيدة وكتفاك للخلف وصدرك مفتوحًا وجذعك مشدودًا.','ضع أصابع قدميك بشكل مسطح على حافة منصة مرتفعة ووزّع وزنك بالتساوي على كلتا رجليك.','ارتفع ببطء على مقدمة قدميك، رافعًا كعبيك عن الأرض بأقصى ما يمكن بشكل مريح، مع تقلص عضلات الساق بالكامل.','أنزل كعبيك بلطف إلى الأرض، مع الحفاظ على التحكم طوال الحركة.','نفّذ 15-25 تكرارًا لكل مجموعة، مع التركيز على حركات متحكم بها ومقصودة.'], ARRAY['Stand upright with feet hip-width apart, maintaining good posture with shoulders back, chest open, and core engaged.','Place your toes flat on the end of a high platform and distribute your weight evenly across both legs.','Slowly rise onto the balls of your feet, lifting heels off the ground as high as comfortably possible, contracting the calves fully.','Gently lower your heels back to the floor, maintaining control throughout the movement.','Perform 15-25 repetitions per set, emphasizing controlled and deliberate movements.'], ARRAY['gastrocnemius'], ARRAY['soleus','plantaris','tibialis posterior','peroneals'], NULL),
  ('رفع الكعب وقوفًا بالدمبل', 'Standing Calf Raise With Dumbbell', 'legs', 'dumbbell', 'قف بشكل مستقيم وقدماك بعرض الوركين، وأمسك دمبل بكل يد. شد جذعك للثبات. ارتفع ببطء على مقدمة قدميك برفع كعبيك بأقصى ما يمكن. أنزل تدريجيًا بتحكم. نفّذ 10-15 تكرارًا لكل مجموعة.', 'Stand upright with feet hip-width apart, holding a dumbbell in each hand. Engage your core for stability. Slowly rise onto the balls of your feet by lifting your heels as high as possible. Gradually lower back down with control. Perform 10-15 reps per set.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Dumbbell-Calf-Raise.gif', ARRAY['قف بشكل مستقيم وقدماك بعرض الوركين، وأمسك دمبل بكل يد مع ترك ذراعيك مرتاحتين بجانبيك.','شد عضلات جذعك للثبات، وحافظ على كتفيك للخلف، وحافظ على استقامة عمودك الفقري.','ارتفع ببطء على مقدمة قدميك برفع كعبيك بأقصى ما يمكن.','أنزل كعبيك تدريجيًا إلى وضع البداية بشكل متحكم به.','نفّذ العدد المطلوب من التكرارات، عادة 10-15 تكرارًا لكل مجموعة، مع التركيز على حركات بطيئة ومتحكم بها.'], ARRAY['Stand upright with feet hip-width apart, holding a dumbbell in each hand, arms relaxed by your sides.','Engage your core muscles for stability, keep shoulders back, and maintain neutral spine alignment.','Slowly rise onto the balls of your feet by lifting your heels as high as possible.','Gradually lower your heels back down to the starting position in a controlled manner.','Perform the desired repetitions, typically 10-15 reps per set, emphasizing slow and controlled movements.'], ARRAY['gastrocnemius'], ARRAY['soleus','plantaris','tibialis posterior','flexor hallucis longus','flexor digitorum longus','peroneus longus','peroneus brevis'], NULL),
  ('المشي', 'Walking', 'cardio', 'none', 'قف بشكل مستقيم وابدأ المشي بمعدل ثابت ومريح. حرّك ذراعيك بشكل طبيعي وحافظ على وضعية جيدة. ضع كعبك أولًا على الأرض ثم انتقل للدفع بأصابع قدمك. هذا النشاط البسيط يشغّل العديد من عضلات الجزء السفلي من الجسم الكبيرة والصغيرة.', 'Stand tall and begin walking at a comfortable, steady pace. Swing your arms naturally and maintain good posture. Land on your heel and roll through to push off with your toes. This simple activity works many large and small muscle groups in the lower body.', 'https://fitnessprogramer.com/wp-content/uploads/2021/09/Walking.gif', ARRAY['قف بشكل مستقيم وابدأ المشي بمعدل ثابت ومريح.','حرّك ذراعيك بشكل طبيعي وحافظ على وضعية جيدة مع كتفين مرتاحتين.','ضع كعبك أولًا على الأرض ثم انتقل للدفع بأصابع قدمك.','حافظ على تنفس ثابت واستمر للمدة أو المسافة المطلوبة.'], ARRAY['Stand tall and begin walking at a comfortable, steady pace.','Swing your arms naturally and maintain good posture with shoulders relaxed.','Land on your heel and roll through to push off with your toes.','Maintain a steady breathing rhythm and continue for the desired duration or distance.'], ARRAY['cardio'], ARRAY['quadriceps','glutes','hamstrings','tensor fasciae latae','sartorius','adductor magnus','adductor longus','adductor brevis','pectineus','psoas','obliques','calves','tibialis anterior'], 'beginner'),
  ('بيربي مع وثبة طويلة', 'Burpee Long Jump', 'cardio', 'none', 'قف بشكل مستقيم وقدماك بعرض الكتفين. انخفض في قرفصاء وضع يديك على الأرض واقفز بقدميك للخلف إلى وضعية البلانك العالي. نفّذ تمرين ضغط اختياريًا. اقفز بقدميك للأمام، ثم لوّح بذراعيك للخلف واقفز بانفجارية للأمام بأقصى مسافة، مع الهبوط بلطف. استدر وكرر.', 'Stand tall with feet shoulder-width apart. Drop into a squat, hands on the floor, and jump feet back into a high plank. Optionally perform a push-up. Jump feet forward, then swing your arms back and explosively jump forward as far as possible, landing softly. Turn around and repeat.', 'https://fitnessprogramer.com/wp-content/uploads/2025/10/Burpee-Long-Jump.gif', ARRAY['قف بشكل مستقيم وقدماك بعرض الكتفين. حافظ على شد جذعك وذراعيك مرتاحتين بجانبيك.','انخفض في وضعية القرفصاء وضع يديك على الأرض أمامك. اقفز أو اخطُ بقدميك للخلف إلى وضعية البلانك العالي.','نفّذ تمرين ضغط (اختياري).','اقفز أو اخطُ بقدميك للأمام بحيث تلامسان الأرض خارج يديك مباشرة. حافظ على رفع صدرك أثناء التحضير للقفز.','لوّح بذراعيك للخلف، ثم اقفز بانفجارية للأمام بأقصى مسافة ممكنة. اهبط بلطف وركبتاك مثنيتان مع توزيع الوزن بالتساوي.','استدر أو اسِر للخلف إلى نقطة البداية. كرر للعدد المطلوب من التكرارات أو المسافة.'], ARRAY['Stand tall with feet shoulder-width apart. Keep your core braced and arms relaxed at your sides.','Drop into a squat position and place your hands on the floor in front of you. Jump or step your feet back into a high plank position.','Perform a push-up (optional).','Jump or step your feet forward so they land just outside your hands. Keep your chest lifted as you prepare to jump.','Swing your arms backward, then explosively jump forward as far as possible. Land softly with knees bent and weight distributed evenly.','Turn around or walk backward to your starting point. Repeat for the desired number of reps or distance.'], ARRAY['cardio','full body'], ARRAY['quadriceps','glutes','pectoralis major','calves','triceps brachii','rectus abdominis','hamstrings','obliques','anterior deltoid','hip flexors','trapezius','biceps brachii'], 'intermediate'),
  ('ضغط البنش بالبار', 'Barbell Bench Press', 'chest', 'barbell', 'استلق على بنش مسطح بحيث تكون عيناك مباشرة تحت البار، قدماك مسطحتان وركبتاك مثنيتان بزاوية 90 درجة، وقبضتك أوسع قليلًا من عرض الكتفين. حرر البار فوق صدرك مع فرد مرفقيك. اشهق، وشد جذعك، وأنزل البار ببطء إلى الجزء السفلي من صدرك. ادفع البار للأعلى في قوس خفيف، مع الزفير أثناء الدفع بالصدر والترايسبس، وقفل مرفقيك في الأعلى. حافظ على شد ظهرك العلوي وكرر للعدد المطلوب من التكرارات.', 'Lie on a flat bench with eyes directly under the bar, feet flat, knees bent at ~90°, grip slightly wider than shoulder-width. Unrack the bar over your chest with elbows extended. Inhale, brace your core, and lower the bar slowly to the lower chest. Push the bar upward in a slight arc, exhaling as you drive through chest and triceps, locking out at the top. Maintain upper back tightness and repeat for prescribed reps.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Barbell-Bench-Press.gif', ARRAY['استلق على بنش مسطح بحيث تكون عيناك مباشرة تحت البار. قدماك مسطحتان على الأرض وركبتاك مثنيتان بزاوية 90 درجة تقريبًا. أمسك البار بقبضة أوسع قليلًا من عرض الكتفين.','حرر البار من الحامل وأنزله فوق صدرك مع فرد مرفقيك بالكامل. اشهق، وشد جذعك، وأنزل البار ببطء إلى الجزء السفلي من صدرك.','ادفع البار للأعلى في قوس خفيف نحو عينيك. ازفر وأنت تدفع بصدرك وترايسبس، مع قفل مرفقيك في الأعلى.','حافظ على شد ظهرك العلوي وكرر للعدد المطلوب من التكرارات.'], ARRAY['Lie on a flat bench with eyes directly under the bar. Feet flat on the ground, knees bent at ~90°. Grip the bar with a slightly wider than shoulder-width grip.','Unrack the bar and bring it over your chest, elbows fully extended. Inhale, brace your core, and lower the bar slowly to the lower portion of your chest.','Push the bar upward in a slight arc back toward your eyes. Exhale as you drive through the chest and triceps, locking out the elbows at the top.','Maintain upper back tightness and repeat for prescribed reps.'], ARRAY['pectoralis major sternal'], ARRAY['anterior deltoid','triceps','biceps brachii'], NULL),
  ('ضغط البنش المائل بالبار', 'Incline Barbell Bench Press', 'chest', 'barbell', 'اضبط البنش المائل بزاوية 30-45 درجة. حمّل البار بوزن مناسب. استلق بقدميك مثبتتين على الأرض ورأسك مستندًا على البنش. أمسك البار بقبضة أوسع قليلًا من عرض الكتفين. حرر البار وأنزله إلى صدرك العلوي مع فتح مرفقيك للجانبين. اضغط للأعلى إلى وضع البداية مع الزفير. كرر للعدد المطلوب من التكرارات.', 'Set up the incline bench at 30-45 degrees. Load the barbell appropriately. Lie down with feet firmly on the ground and head resting on the bench. Grab the barbell slightly wider than shoulder-width. Unrack and bring it down to your upper chest with elbows flared out. Press back up to the starting position, exhaling as you push. Repeat for desired reps.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Incline-Barbell-Bench-Press.gif', ARRAY['اضبط البنش المائل بالزاوية المطلوبة (30 إلى 45 درجة).','حمّل البار بوزن مناسب لمستوى لياقتك وهدفك.','استلق على البنش بقدميك مثبتتين بثبات على الأرض ورأسك مستندًا على البنش.','أمسك البار بقبضة أوسع قليلًا من عرض الكتفين.','حرر البار من الحامل وأنزله إلى صدرك العلوي مع فتح مرفقيك للجانبين.','اضغط بالبار للأعلى إلى وضع البداية، مع الزفير أثناء الدفع.','كرر للعدد المطلوب من التكرارات.'], ARRAY['Set up the incline bench at the desired angle (30 to 45 degrees).','Load the barbell with an appropriate weight for your fitness level and goals.','Lie down on the bench with your feet firmly on the ground and your head resting on the bench.','Grab the barbell with a grip slightly wider than shoulder-width apart.','Unrack the barbell and bring it down to your upper chest, with your elbows flared out to the sides.','Press the barbell back up to the starting position, exhaling as you push.','Repeat for the desired number of reps.'], ARRAY['pectoralis major clavicular'], ARRAY['anterior deltoid','triceps brachii','pectoralis major sternal','biceps brachii'], NULL),
  ('فتح الصدر بالدمبل', 'Dumbbell Fly', 'chest', 'dumbbell', 'استلق بشكل مسطح على بنش، وأمسك دمبل بكل يد بقبضة محايدة، وذراعاك مفرودتان فوق صدرك مع ثني خفيف في مرفقيك. أنزل الدمبل ببطء في قوس واسع حتى يصبحا بمستوى صدرك. اشعر بشدّ في الصدر دون إفراط في التمديد. اعكس الحركة بالضغط على عضلات صدرك وإعادة الدمبل للأعلى بنفس القوس.', 'Lie flat on a bench, holding a dumbbell in each hand with a neutral grip, arms extended above your chest with a slight bend in the elbows. Slowly lower the dumbbells in a wide arc until level with your chest. Feel a stretch in the chest without overstretching. Reverse by squeezing your chest muscles and bringing the dumbbells back up in the same arc.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Dumbbell-Fly.gif', ARRAY['استلق بشكل مسطح على بنش. أمسك دمبل بكل يد بقبضة محايدة (راحتا يديك متقابلتان). مدّ ذراعيك مباشرة فوق صدرك مع ثني خفيف في مرفقيك لتقليل الضغط على المفاصل.','أنزل الدمبل ببطء في قوس واسع، محافظًا على الثني الخفيف في مرفقيك. يجب أن تتحرك ذراعاك للخارج والأسفل حتى تصبحا بمستوى صدرك أو أسفله قليلًا.','ركز على الشعور بشدّ في عضلات صدرك دون الإفراط في التمديد أو التأثير على ثبات كتفيك.','اعكس الحركة بالضغط على عضلات صدرك وإعادة الدمبل للأعلى بنفس القوس إلى وضع البداية.'], ARRAY['Lie flat on a bench. Hold a dumbbell in each hand with a neutral grip (palms facing each other). Extend your arms straight above your chest, keeping a slight bend in your elbows to reduce joint strain.','Slowly lower the dumbbells in a wide arc, maintaining the slight bend in your elbows. Your arms should move outward and downward until they are level with your chest or slightly below.','Focus on feeling a stretch in your chest muscles without overstretching or compromising shoulder stability.','Reverse the motion by squeezing your chest muscles and bringing the dumbbells back up in the same arc to the starting position.'], ARRAY['pectoralis major sternal'], ARRAY['pectoralis major clavicular','anterior deltoid','biceps brachii'], NULL),
  ('سحب الدمبل خلف الرأس', 'Dumbbell Pullover', 'chest', 'dumbbell', 'استلق على بنش مسطح بحيث يكون ظهرك العلوي وكتفاك فقط مرتكزين عليه، وقدماك مسطحتان على الأرض. أمسك دمبل واحد بكلتا يديك فوق صدرك مع فرد ذراعيك. اشهق، وشد جذعك، وحرك الدمبل ببطء في قوس نحو الخلف والأسفل خلف رأسك مع ثني خفيف في مرفقيك. بعد الشعور بشدّ في الظهر والصدر، اعكس الحركة بسحب الدمبل فوق صدرك. ازفر في الأعلى وكرر.', 'Lie on a flat bench with only your upper back and shoulders supported, feet flat on the ground. Hold one dumbbell with both hands above your chest, arms extended. Inhale, brace your core, and slowly arc the dumbbell back and down behind your head with a slight bend in the elbows. Once you feel a stretch in your lats and chest, reverse by pulling the dumbbell back over your chest. Exhale at the top and repeat.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Dumbbell-Pullover.gif', ARRAY['استلق على بنش مسطح بحيث يكون ظهرك العلوي وكتفاك فقط مرتكزين عليه، وقدماك مسطحتان على الأرض.','أمسك دمبل واحد بكلتا يديك من تحت القرص الداخلي، وذراعاك مفرودتان فوق صدرك.','اشهق، وشد جذعك، وحرك الدمبل ببطء في قوس نحو الخلف والأسفل خلف رأسك، مع ثني خفيف في مرفقيك.','بعد الشعور بشدّ في عضلات الظهر العريضة والصدر، اعكس الحركة بسحب الدمبل مرة أخرى فوق صدرك باستخدام الظهر أو الصدر.','ازفر في الأعلى وكرر للعدد المطلوب من التكرارات بحركة سلسة ومتحكم بها.'], ARRAY['Lie on a flat bench with only your upper back and shoulders supported. Keep your feet flat on the ground.','Hold one dumbbell with both hands under the inner plate, arms extended above your chest.','Inhale, brace your core, and slowly arc the dumbbell back and down behind your head. Maintain a slight bend in the elbows.','Once you feel a stretch in your lats and chest, reverse the motion by pulling the dumbbell back over your chest using your lats or chest.','Exhale at the top and repeat for desired reps with smooth, controlled movement.'], ARRAY['pectoralis major sternal'], ARRAY['latissimus dorsi','posterior deltoid','teres major','triceps long head','pectoralis minor','rhomboids','serratus anterior','levator scapulae'], NULL),
  ('فتح الصدر بجهاز الببفلاي', 'Pec Deck Fly (Machine Fly)', 'chest', 'machine', 'اضبط المقعد بحيث تكون المقابض عند مستوى الصدر مع ذراعيك خلف جذعك قليلًا في البداية. حافظ على ثني خفيف في مرفقيك. ازفر وقرّب ذراعيك أمام صدرك بحركة عناق، مع الضغط على صدرك في القمة. اعكس الحركة ببطء حتى تشعر بشدّ خفيف في الصدر.', 'Set the seat so handles are at chest level with arms slightly behind your torso to begin. Keep a slight bend in the elbows. Exhale and bring the arms together in front of your chest in a hugging motion, squeezing your chest at the peak. Slowly reverse until you feel a mild stretch in the chest.', NULL, ARRAY['اضبط المقعد بحيث تكون المقابض عند مستوى الصدر. اضبط وسائد الذراع بحيث تكون ذراعاك خلف جذعك قليلًا في البداية.','ضع قدميك مسطحتين، واضغط ظهرك على الوسادة، وأمسك المقابض أو ارتكز بساعديك على الوسائد.','حافظ على ثني خفيف في مرفقيك لحماية مفاصلك.','ازفر وقرّب ذراعيك أمام صدرك بحركة عناق. ركز على الضغط على عضلات صدرك في القمة.','اعكس الحركة ببطء حتى تشعر بشدّ خفيف في الصدر. تجنب ترك الأوزان تصطدم أو الإفراط في التمديد.'], ARRAY['Set the seat so handles are at chest level. Adjust arm pads so your arms are slightly behind your torso to begin.','Place your feet flat, back pressed against the pad, and grasp the handles or rest forearms against pads.','Keep a slight bend in the elbows to protect your joints.','Exhale and bring the arms together in front of your chest in a hugging motion. Focus on squeezing your chest muscles at the peak.','Slowly reverse the movement until you feel a mild stretch in the chest. Avoid letting weights slam or overstretching.'], ARRAY['pectoralis major sternal'], ARRAY['pectoralis major clavicular','pectoralis minor','anterior deltoid','biceps short head','serratus anterior'], NULL),
  ('تقاطع الكابل السفلي للصدر', 'Low Cable Crossover', 'chest', 'cable', 'اضبط جهاز الكابل عند أدنى وضع مع تثبيت المقابض على كل جانب. قف في المنتصف مواجهًا الجهاز، وقدماك بعرض الكتفين، وأمسك المقابض عند مستوى الكتف. اخطُ للأمام، واثنِ ركبتيك قليلًا، وانحنِ للأمام مع استقامة ظهرك. مع ثني خفيف في ذراعيك، اسحب المقابض للأعلى ونحو خط وسط جسمك. توقف لحظة، ثم عد ببطء إلى وضع البداية.', 'Set cable machine to lowest setting with handles attached on each side. Stand centered facing the machine, feet shoulder-width apart, holding handles at shoulder height. Step forward, bend knees slightly, lean forward with a straight back. With slight arm bend, draw the handles upward and toward the midline of your body. Pause briefly, then slowly return to starting position.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Low-Cable-Crossover.gif', ARRAY['اضبط جهاز الكابل عند أدنى وضع مع تثبيت المقابض على كل جانب.','قف في المنتصف مواجهًا الجهاز، وقدماك بعرض الكتفين، وأمسك المقابض عند مستوى الكتف.','اخطُ بقدم واحدة للأمام، واثنِ ركبتيك قليلًا، وانحنِ للأمام مع الحفاظ على استقامة ظهرك.','ضع يديك بجانبك أسفل الوركين قليلًا.','مع ثني خفيف في ذراعيك، اسحب الأوزان للأعلى ونحو خط وسط جسمك.','توقف لحظة، ثم عد ببطء إلى وضع البداية.','كرر للعدد المطلوب من التكرارات، ثم بدّل الجانبين.'], ARRAY['Set cable machine to lowest setting with handles attached on each side.','Stand centered facing the machine, feet shoulder-width apart, holding handles at shoulder height.','Step forward with one foot, bend knees slightly, and lean forward while maintaining a straight back.','Position hands at your sides just below hips.','With slight arm bend, draw your weights upward and toward the midline of your body.','Pause briefly, then slowly return to starting position.','Repeat desired repetitions, then switch sides.'], ARRAY['pectoralis major sternal'], ARRAY['pectoralis major clavicular','anterior deltoid','biceps short head'], NULL),
  ('تجعيد المعصم بالدمبل', 'Dumbbell Wrist Curl', 'arms', 'dumbbell', 'اجلس على بنش وأمسك دمبل بكل يد، مع ارتكاز ساعديك على فخذيك وراحتا يديك للأعلى. اترك الدمبل يتدحرج نحو أصابعك، ثم اثنِ معصميك لرفعه للأعلى. اضغط في الأعلى، ثم أنزل بتحكم وكرر.', 'Sit on a bench holding a dumbbell in each hand, forearms resting on your thighs, palms facing up. Let the dumbbells roll down to your fingers, then curl them back up by flexing your wrists. Squeeze at the top, then lower with control and repeat.', 'https://fitnessprogramer.com/wp-content/uploads/2021/06/Dumbbell-Wrist-Curl.gif', ARRAY['اجلس على بنش وأمسك دمبل بكل يد، مع ارتكاز ساعديك على فخذيك ومعصميك بعد الركبتين قليلًا، وراحتا يديك للأعلى.','اترك الدمبل يتدحرج نحو أصابعك، ثم اثنِ معصميك لرفعه للأعلى.','اضغط في الأعلى، ثم أنزل بتحكم وكرر.'], ARRAY['Sit on a bench holding a dumbbell in each hand, forearms resting on your thighs with wrists just past your knees, palms facing up.','Let the dumbbells roll down to your fingers, then curl them back up by flexing your wrists.','Squeeze at the top, then lower with control and repeat.'], ARRAY['forearm'], ARRAY[]::text[], NULL),
  ('تجعيد المعصم العكسي بالبار', 'Barbell Reverse Wrist Curl', 'arms', 'barbell', 'اجلس على بنش وأمسك البار بقبضة علوية، مع ارتكاز ساعديك على فخذيك وراحتا يديك للأسفل. أنزل البار بثني معصميك للأسفل، ثم اثنِ معصميك للأعلى لرفعه. اضغط في الأعلى، ثم أنزل بتحكم وكرر.', 'Sit on a bench holding a barbell with an overhand grip, forearms resting on your thighs, palms facing down. Lower the bar by bending your wrists downward, then curl it back up by extending your wrists. Squeeze at the top, then lower with control and repeat.', 'https://fitnessprogramer.com/wp-content/uploads/2021/06/Barbell-Reverse-Wrist-Curl.gif', ARRAY['اجلس على بنش وأمسك البار بقبضة علوية، مع ارتكاز ساعديك على فخذيك ومعصميك بعد الركبتين قليلًا، وراحتا يديك للأسفل.','أنزل البار بثني معصميك للأسفل، ثم اثنِ معصميك للأعلى لرفعه.','اضغط في الأعلى، ثم أنزل بتحكم وكرر.'], ARRAY['Sit on a bench holding a barbell with an overhand grip, forearms resting on your thighs with wrists just past your knees, palms facing down.','Lower the bar by bending your wrists downward, then curl it back up by extending your wrists.','Squeeze at the top, then lower with control and repeat.'], ARRAY['forearm'], ARRAY[]::text[], NULL),
  ('الخطف والنتر (كلين آند جيرك)', 'Clean and Jerk', 'full_body', 'barbell', 'اتخذ وضعية البداية بقدمين بعرض الوركين، والبار فوق منتصف قدمك. حافظ على استقامة ظهرك وصدرك مرفوعًا وأنت ترفع البار، مع المد الانفجاري من خلال وركيك، ثم التقطه في وضعية الحمل الأمامي. انخفض بثني ركبتيك، وادفع للأعلى، وادفع تحت البار مع قفل ذراعيك فوق رأسك. ثبّت واقفًا.', 'Set up with feet hip-width apart, barbell over mid-foot. Keep back flat and chest up as you lift the bar, extending explosively through the hips, then catch it in a front rack position. Dip by bending the knees, drive upward, and push under the bar, locking arms overhead. Stabilize and stand upright.', 'https://fitnessprogramer.com/wp-content/uploads/2025/06/clean-and-jerk.gif', ARRAY['اتخذ وضعية البداية بقدمين بعرض الوركين، والبار فوق منتصف قدمك، ويداك أوسع قليلًا من عرض الكتفين.','حافظ على استقامة ظهرك وصدرك مرفوعًا وأنت ترفع البار من الأرض. مدّ وركيك بانفجارية مع هز كتفيك لسحب البار للأعلى. انخفض تحت البار والتقطه في وضعية الحمل الأمامي مع رفع مرفقيك.','انخفض قليلًا بثني ركبتيك، ثم ادفع للأعلى من خلال رجليك. انقسم أو ادفع تحت البار بسرعة، مع قفل ذراعيك فوق رأسك. ثبّت واقفًا لإكمال الرفعة.'], ARRAY['Set up with feet hip-width apart, barbell over mid-foot, and hands slightly wider than shoulder-width.','Keep the back flat and chest up as you lift the bar from the ground. Explosively extend through the hips and shrug, pulling the bar upward. Drop under the bar and catch it in a front rack position with elbows high.','Dip slightly by bending the knees, then drive upward through the legs. Split or push under the bar quickly, locking out the arms overhead. Stabilize and stand upright to complete the lift.'], ARRAY['full body'], ARRAY['glutes','hamstrings','quadriceps','calves','trapezius','deltoids','triceps','latissimus dorsi','abdominals','erector spinae','obliques'], 'advanced'),
  ('دفع الوركين بالبار', 'Barbell Hip Thrust', 'glutes', 'barbell', 'اجلس على الأرض وظهرك العلوي مستند على بنش والبار فوق وركيك مرتكزًا عبر ثنيتهما. اثنِ ركبتيك وثبّت قدميك مسطحتين بعرض الوركين. شد جذعك وادفع عبر كعبيك لرفع وركيك للأعلى. في الأعلى اضغط بمقعدتك وتوقف عندما يصبح جذعك موازيًا للأرض. أنزل ببطء وكرر.', 'Sit on the floor with your upper back against a bench, a barbell over your hips resting across the crease. Bend your knees, feet flat hip-width apart. Brace your core and drive through your heels to lift your hips upward. At the top, squeeze your glutes, pausing when torso is parallel to the floor. Lower slowly and repeat.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Barbell-Hip-Thrust.gif', ARRAY['اجلس على الأرض وظهرك العلوي مستند على بنش والبار فوق وركيك.','دحرج البار ليرتكز عبر ثنية وركيك، مع وضع وسادة أو منشفة تحته للراحة.','اثنِ ركبتيك وثبّت قدميك مسطحتين بعرض الوركين.','شد جذعك وادفع عبر كعبيك لرفع وركيك للأعلى.','في الأعلى، اضغط بمقعدتك وتوقف عندما يصبح جذعك موازيًا للأرض.','أنزل ببطء وكرر للعدد المطلوب من التكرارات.'], ARRAY['Sit on the floor with your upper back against a bench and a barbell over your hips.','Roll the bar to rest across the crease of your hips, placing a pad or towel underneath for comfort.','Bend your knees and plant your feet flat, hip-width apart.','Brace your core and drive through your heels to lift the hips upward.','At the top, squeeze your glutes and pause when your torso is parallel to the floor.','Lower slowly back down and repeat for your desired number of reps.'], ARRAY['gluteus maximus'], ARRAY['quadriceps','adductor magnus','erector spinae','hip external rotators','hamstrings','tibialis anterior'], NULL),
  ('سكوات بالبار', 'Barbell Squat', 'legs', 'barbell', 'اضبط البار على حامل السكوات عند مستوى أقل من الكتف بقليل، مرتكزًا على أعلى الترابيزيوس. أمسك البار بقوة وارفعه عن الحامل. اخطُ للخلف، وضع قدميك بعرض الكتفين، وشد جذعك. أنزل جسمك بدفع وركيك للخلف وثني ركبتيك حتى تصبح فخذاك موازيتين للأرض. ادفع عبر كعبيك للعودة إلى وضع الوقوف.', 'Set the barbell on a squat rack just below shoulder height, resting across your upper traps. Grip the bar firmly and lift it off the rack. Step back, feet shoulder-width apart, brace your core. Lower your body by pushing your hips back and bending the knees until thighs are parallel to the ground. Drive through your heels to return to standing.', NULL, ARRAY['اضبط البار على حامل السكوات عند مستوى أقل من الكتف بقليل. قف تحته وضع البار عبر أعلى الترابيزيوس أو خلف الكتفين.','أمسك البار بقوة، واسحب مرفقيك للأسفل وتحت البار، وارفعه عن الحامل.','اخطُ للخلف، وضع قدميك بعرض الكتفين، وشد جذعك.','أنزل جسمك بدفع وركيك للخلف وثني ركبتيك، مع الحفاظ على صدرك مرفوعًا.','انزل حتى تصبح فخذاك موازيتين للأرض أو أدنى إذا سمحت مرونتك.','ادفع عبر كعبيك للعودة إلى وضع الوقوف، مع الحفاظ على عمودك الفقري محايدًا.'], ARRAY['Set the barbell on a squat rack just below shoulder height. Step under it and rest the bar across your upper traps or rear delts.','Grip the bar firmly, pull your elbows down and under, and lift the bar off the rack.','Step back, set your feet shoulder-width apart, and brace your core.','Lower your body by pushing your hips back and bending the knees, keeping your chest upright.','Descend until your thighs are parallel to the ground or lower if mobility allows.','Drive through your heels to return to the standing position, keeping the spine neutral.'], ARRAY['quadriceps'], ARRAY['glutes','adductor magnus','soleus','hamstrings','gastrocnemius','erector spinae','rectus abdominis','obliques'], NULL),
  ('سكوات جوبلت بالدمبل', 'Dumbbell Goblet Squat', 'legs', 'dumbbell', 'أمسك الدمبل بشكل عمودي بكلتا يديك قريبًا من صدرك. قف وقدماك بعرض الكتفين. شد جذعك وادفع وركيك للخلف مع ثني ركبتيك للانخفاض في سكوات عميق مع الحفاظ على الدمبل عند مستوى الصدر. ادفع عبر كعبيك للعودة إلى وضع الوقوف مع فرد وركيك بالكامل.', 'Hold a dumbbell vertically with both hands close to your chest. Stand with feet shoulder-width apart. Engage your core and push your hips back, bending your knees to lower into a deep squat while keeping the dumbbell at chest level. Drive through your heels to return to standing, fully extending your hips.', 'https://fitnessprogramer.com/wp-content/uploads/2023/01/Dumbbell-Goblet-Squat.gif', ARRAY['أمسك الدمبل بشكل عمودي بكلتا يديك من تحت الجزء العلوي (الطرف الموزون)، قريبًا من صدرك.','قف وقدماك بعرض الكتفين، وأصابع قدميك متجهة للخارج قليلًا.','شد جذعك وحافظ على صدرك مرفوعًا طوال الحركة.','ادفع وركيك للخلف واثنِ ركبتيك، منخفضًا في سكوات عميق مع الحفاظ على الدمبل عند مستوى الصدر.','حافظ على مرفقيك داخل ركبتيك عند الوصول لأقصى عمق، وتجنب انهيار الركبتين للداخل.','ادفع عبر كعبيك للعودة إلى وضع الوقوف، مع فرد وركيك بالكامل في الأعلى.'], ARRAY['Hold a dumbbell vertically with both hands under the top portion (the weighted end), close to your chest.','Stand with feet shoulder-width apart, toes slightly turned out.','Engage your core and keep your chest lifted throughout the movement.','Push your hips back and bend your knees, lowering into a deep squat while keeping the dumbbell at chest level.','Keep your elbows inside your knees as you reach full depth, and avoid letting the knees collapse inward.','Drive through your heels to return to the standing position, fully extending your hips at the top.'], ARRAY['quadriceps'], ARRAY['glutes','adductors','soleus','gastrocnemius','hamstrings','tibialis anterior','rectus abdominis','obliques','erector spinae'], 'beginner'),
  ('ضغلة الأرجل (ليج برس)', 'Leg Press', 'legs', 'machine', 'اجلس على المقعد وظهرك مستند على المسند وقدماك مسطحتان على المنصة وركبتاك مثنيتان بزاوية 90 درجة. ضع قدميك بعرض الوركين. اضغط بالمنصة بقدميك وفرد رجليك. اثنِ ركبتيك ببطء وأنزل الوزن مرة أخرى بتحكم.', 'Sit on the seat with your back against the backrest, feet flat on the platform, knees bent at 90 degrees. Position your feet hip-width apart. Push against the platform with your feet and extend your legs. Slowly bend your knees and lower the weight back down with control.', 'https://fitnessprogramer.com/wp-content/uploads/2015/11/Leg-Press.gif', ARRAY['اجلس على المقعد وظهرك مستند على المسند وقدماك مسطحتان على المنصة. يجب أن تكون ركبتاك مثنيتين بزاوية 90 درجة.','أضف أقراص الوزن على الجهاز حسب شدة التمرين المطلوبة.','ضع قدميك بعرض الوركين على المنصة، وأصابع قدميك متجهة للأمام أو للخارج قليلًا.','أمسك المقابض أو الدعامات الجانبية للجهاز للثبات. اشهق بعمق وشد عضلات جذعك.','اضغط بالمنصة بقدميك وفرد رجليك، مما يدفع المنصة بعيدًا عن جسمك.','اثنِ ركبتيك ببطء وأنزل الوزن مرة أخرى، بحيث تصل ركبتاك لزاوية 90 درجة أو أبعد قليلًا.','أكمل العدد المطلوب من التكرارات، مع الحفاظ على التحكم والأداء الصحيح.'], ARRAY['Sit on the seat with your back against the backrest and your feet resting flat on the platform. Your knees should be bent at a 90-degree angle.','Add weight plates to the machine according to your desired intensity level.','Position your feet hip-width apart on the platform, with toes pointing forward or slightly outward.','Grip the handles or side supports of the machine for stability. Take a deep breath and brace your core muscles.','Push against the platform with your feet and extend your legs, driving the platform away from your body.','Slowly bend your knees and lower the weight back down, allowing your knees to reach a 90-degree angle or slightly beyond.','Complete the desired number of repetitions, maintaining control and proper form throughout.'], ARRAY['quadriceps'], ARRAY['glutes','adductor magnus','soleus','hamstrings','gastrocnemius'], NULL),
  ('رفعة الديدلفت بالبار', 'Barbell Deadlift', 'back', 'barbell', 'قف وقدماك بعرض الكتفين، والبار على الأرض أمامك. انحنِ وأمسك البار بقبضة أوسع قليلًا من عرض الكتفين. اثنِ ركبتيك، وأنزل وركيك مع استقامة ظهرك وصدرك مرفوعًا. شد جذعك، وحافظ على قرب البار من جسمك، وارفع باستخدام رجليك ومقعدتك وعضلات ظهرك. توقف لحظة في وضع الوقوف، ثم أنزل البار بتحكم.', 'Stand with feet shoulder-width apart, barbell on ground in front. Bend down and grasp bar slightly wider than shoulder-width. Bend knees, lower hips keeping back straight and chest up. Brace your core, keep the bar close to your body, and lift using your legs, glutes, and back muscles. Pause briefly at standing, then lower back down with control.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Barbell-Deadlift.gif', ARRAY['قف وقدماك بعرض الكتفين، وأصابع قدميك متجهة للأمام مباشرة، والبار على الأرض أمامك.','انحنِ وأمسك البار بقبضة أوسع قليلًا من عرض الكتفين باستخدام قبضة علوية أو مختلطة.','اثنِ ركبتيك، وأنزل وركيك مع الحفاظ على استقامة ظهرك وصدرك مرفوعًا، وحافظ على وضع محايد لرأسك ورقبتك.','اشهق بعمق وشد عضلات جذعك لتثبيت عمودك الفقري.','حافظ على قرب البار من جسمك، وارفع باستخدام رجليك ومقعدتك وعضلات ظهرك.','توقف لحظة في وضع الوقوف، ثم أنزل البار إلى الأرض بأداء متحكم به.'], ARRAY['Stand with feet shoulder-width apart, toes pointed straight ahead, barbell on ground in front.','Bend down and grasp bar slightly wider than shoulder-width using overhand or mixed grip.','Bend knees, lower hips while keeping back straight and chest up, maintain neutral head/neck position.','Take deep breath and brace core muscles to stabilize spine.','Keep bar close to body, lift using legs, glutes, and back muscles.','Pause briefly at standing position, then lower bar back to ground with controlled form.'], ARRAY['glutes','erector spinae','back','hip','legs'], ARRAY['quadriceps','adductor magnus','hamstrings','soleus','trapezius','levator scapulae','latissimus dorsi','rhomboids'], NULL),
  ('لنج الانحناء (كيرتسي)', 'Curtsy Lunge', 'legs', 'none', 'قف وقدماك بعرض الوركين، وضع يديك أمام صدرك للتوازن. اخطُ بقدم واحدة قُطريًا للخلف متقاطعة خلف الرجل الأخرى. اثنِ كلتا ركبتيك حتى يصبح الفخذ الأمامي موازيًا للأرض. ادفع عبر كعبك الأمامي للعودة إلى وضع البداية. بدّل بين الجانبين.', 'Position yourself with feet hip-width apart, hands in front of your chest for balance. Step diagonally behind you with one foot, crossing it behind the other leg. Bend both knees, lowering until the front thigh is parallel to the floor. Push through your front heel to return to the starting position. Alternate sides.', 'https://fitnessprogramer.com/wp-content/uploads/2023/09/curtsy-lunge.gif', ARRAY['قف وقدماك بعرض الوركين، وضع يديك أمام صدرك للمساعدة في الحفاظ على التوازن.','اخطُ بقدمك اليسرى قُطريًا للخلف، متقاطعة خلف رجلك اليمنى كما لو كنت تنحني تحية.','اثنِ كلتا ركبتيك، منخفضًا بجسمك حتى يصبح فخذك الأيمن موازيًا للأرض، وتكاد ركبتك اليسرى تلمس الأرض.','ادفع عبر كعبك الأيمن لدفع جسمك للعودة إلى وضع البداية. حافظ على استقامة جذعك وصدرك مرفوعًا طوال الحركة.','استمر بالتبديل بين الجانبين للعدد المطلوب من التكرارات.'], ARRAY['Position yourself with your feet spaced hip-width apart, and keep your hands in front of your chest to help maintain balance.','Take a step diagonally behind you with your left foot, crossing it behind your right leg as if you were curtsying.','Bend both knees, lowering your body until your right thigh is parallel to the floor, and your left knee nearly touches the floor.','Push through your right heel to drive yourself back up to the starting position. Keep your torso upright and your chest lifted throughout the movement.','Continue alternating sides for the desired number of repetitions.'], ARRAY['hip','legs'], ARRAY['gluteus medius','gluteus minimus','adductor magnus','soleus','tensor fasciae latae','hamstrings','gastrocnemius','quadratus lumborum','tibialis anterior','rectus abdominis','obliques'], NULL),
  ('الانحناء الجانبي للرقبة بالوزن', 'Weighted Lateral Neck Flexion', 'shoulders', 'none', 'اربط جهاز حزام الرأس بأمان على رأسك وثبّت عليه قرص وزن. استلقِ على جنبك على بنش مائل بحيث تتدلى رأسك خارج نهايته. أنزل قرص الوزن المعلّق بحزام الرأس ليقترب من الأرض. أنزل رأسك حتى تشعر بشدّ خفيف في الجانب المقابل من الرقبة. ازفر بينما ترفع قرص الوزن ببطء وحذر عن طريق ثني رقبتك جانبيًا. حافظ على الوضع لعدّة ثانية أو اثنتين. اشهق بينما تُنزل قرص الوزن ببطء وحذر إلى وضع البداية. كرر لعدد التكرارات المطلوب، ثم كرر على الجانب الآخر.', 'Securely strap the head harness to your head and attach a weight plate to it. Lie on your side on an incline bench with your head extending off the end. Lower the weight plate suspended by the head harness over the floor. Lower your head until you feel a mild stretch in the opposite side of your neck. Exhale as you slowly and carefully lift the weight plate by laterally flexing your neck. Hold the position for a count of one or two. Inhale as you slowly and carefully lower the weight plate to the starting position. Repeat for prescribed reps, then repeat on opposite side.', 'https://fitnessprogramer.com/wp-content/uploads/2022/02/Lying-Weighted-Lateral-Neck-Flexion.gif', ARRAY['اربط جهاز حزام الرأس بأمان على رأسك وثبّت عليه قرص وزن.','استلقِ على جنبك على بنش مائل بحيث تتدلى رأسك خارج نهايته.','أنزل قرص الوزن المعلّق بحزام الرأس ليقترب من الأرض.','أنزل رأسك حتى تشعر بشدّ خفيف في الجانب المقابل من الرقبة.','ازفر بينما ترفع قرص الوزن ببطء وحذر عن طريق ثني رقبتك جانبيًا.','حافظ على الوضع لعدّة ثانية أو اثنتين.','اشهق بينما تُنزل قرص الوزن ببطء وحذر إلى وضع البداية.','كرر لعدد التكرارات المطلوب، ثم كرر على الجانب الآخر.'], ARRAY['Securely strap the head harness to your head and attach a weight plate to it.','Lie on your side on an incline bench with your head extending off the end.','Lower the weight plate suspended by the head harness over the floor.','Lower your head until you feel a mild stretch in the opposite side of your neck.','Exhale as you slowly and carefully lift the weight plate by laterally flexing your neck.','Hold the position for a count of one or two.','Inhale as you slowly and carefully lower the weight plate to the starting position.','Repeat for prescribed reps, then repeat on opposite side.'], ARRAY['neck'], ARRAY['sternocleidomastoid','scalenes','splenius','trapezius upper'], NULL),
  ('مد الرقبة بالوزن أثناء الاستلقاء (حزام الرأس)', 'Weighted Lying Neck Extension (Neck Harness)', 'shoulders', 'none', 'استخدم حزام رأس مزودًا بسلسلة لتثبيت الأوزان. ثبّت قرص وزن صغيرًا على السلسلة بشكل آمن. اضبط بنشًا مائلًا بزاوية 45 درجة. استلق على وجهك على البنش المائل بحيث يرتكز صدرك وبطنك عليه، واترك رأسك يتجاوز الحافة العلوية. ضع حزام الرأس على رأسك واضبطه ليكون محكمًا. اترك رأسك يتدلى للأمام قليلًا ليخلق الوزن شدًا طبيعيًا في مؤخرة الرقبة. مدّ رقبتك ببطء للأعلى رافعًا رأسك والوزن حتى تصبح في خط واحد مع أعلى ظهرك. أنزل رأسك ببطء وتحكم إلى وضع البداية. نفّذ 8-15 تكرارًا لكل مجموعة لمدة 2-4 مجموعات.', 'Use a neck harness with a chain attachment for weights. Attach a small weight plate to the chain, ensuring it is secure. Position an incline bench at a 45-degree angle. Lie face-down on the incline bench with your chest and abdomen supported, letting your head extend beyond the top edge. Place the neck harness on your head, adjusting it to fit snugly. Allow your head to hang forward slightly, letting the weight create a natural stretch in the back of your neck. Slowly extend your neck upward, lifting your head and the attached weight until your head is in line with your upper back. Lower your head back to the starting position in a slow, controlled manner. Perform 8-15 repetitions per set for 2-4 sets.', 'https://fitnessprogramer.com/wp-content/uploads/2021/08/Weighted-Lying-Neck-Extension.gif', ARRAY['استخدم حزام رأس مزودًا بسلسلة لتثبيت الأوزان. ثبّت قرص وزن صغيرًا على السلسلة بشكل آمن.','اضبط بنشًا مائلًا بزاوية 45 درجة.','استلق على وجهك على البنش المائل بحيث يرتكز صدرك وبطنك عليه، واترك رأسك يتجاوز الحافة العلوية للبنش. ضع حزام الرأس على رأسك واضبطه ليكون مريحًا ومحكمًا.','اترك رأسك يتدلى للأمام قليلًا، بحيث يخلق الوزن شدًا طبيعيًا في مؤخرة الرقبة.','مدّ رقبتك ببطء للأعلى، رافعًا رأسك والوزن المثبت معه، حتى تصبح رأسك في خط واحد مع أعلى ظهرك.','أنزل رأسك ببطء وتحكم إلى وضع البداية، مقاومًا سحب الوزن.','نفّذ 8-15 تكرارًا لكل مجموعة، وأكمل 2-4 مجموعات حسب مستوى لياقتك وهدفك.'], ARRAY['Use a neck harness with a chain attachment for weights. Attach a small weight plate to the chain, ensuring it is secure.','Position an incline bench at a 45-degree angle.','Lie face-down on the incline bench with your chest and abdomen supported. Let your head extend beyond the top edge of the bench. Place the neck harness on your head, adjusting it to fit snugly and comfortably.','Allow your head to hang forward slightly, letting the weight create a natural stretch in the back of your neck.','Slowly extend your neck upward, lifting your head and the attached weight. Continue the motion until your head is in line with your upper back.','Lower your head back to the starting position in a slow, controlled manner, resisting the pull of the weight.','Perform 8-15 repetitions per set. Complete 2-4 sets, adjusting based on your fitness level and goals.'], ARRAY['neck'], ARRAY['splenius capitis','trapezius upper','levator scapulae','semispinalis capitis','sternocleidomastoid'], NULL),
  ('ثني الرقبة بالوزن أثناء الاستلقاء (حزام الرأس)', 'Weighted Lying Neck Flexion (Neck Harness)', 'shoulders', 'none', 'استخدم حزام رأس مخصصًا لرفع الأوزان، وثبّت قرص وزن صغيرًا بأمان على سلسلة الحزام. اضبط بنش التمرين بزاوية ميل 45 درجة، واجلس عليه مستندًا بظهرك العلوي بحيث تتجاوز رأسك الحافة. ضع حزام الرأس على رأسك بحيث يكون متوسطًا، واترك رأسك يتدلى للخلف قليلًا. اثنِ رقبتك للأمام مقربًا ذقنك من صدرك ببطء، وتوقف لحظة في الأعلى. أعد رأسك ببطء إلى وضع البداية مقاومًا الوزن. نفّذ 2-4 مجموعات من 8-15 تكرارًا.', 'Use a neck harness designed for weightlifting. Securely attach a small weight plate to the harness chain. Position a workout bench at a 45-degree incline, sit on it and lean back so your upper back is supported while your head extends beyond the edge. Place the neck harness on your head, centered, letting your head hang slightly back. Flex your neck forward, bringing your chin toward your chest slowly. Pause briefly at the top. Slowly return your head to the starting position, resisting the weight. Perform 2-4 sets of 8-15 repetitions.', 'https://fitnessprogramer.com/wp-content/uploads/2021/08/Weighted-Lying-Neck-Flexion.gif', ARRAY['استخدم حزام رأس مخصصًا لرفع الأوزان، وثبّت قرص وزن صغيرًا بأمان على سلسلة الحزام.','اضبط بنش التمرين بزاوية ميل 45 درجة، واجلس عليه مستندًا بظهرك العلوي بحيث تتجاوز رأسك الحافة.','ضع حزام الرأس على رأسك بحيث يكون متوسطًا، واترك رأسك يتدلى للخلف قليلًا في وضع محايد.','اثنِ رقبتك للأمام مقربًا ذقنك من صدرك بحركة بطيئة ومتحكم بها، وتوقف لحظة في أعلى الحركة.','أعد رأسك ببطء إلى وضع البداية مقاومًا سحب الوزن.','نفّذ 2-4 مجموعات من 8-15 تكرارًا حسب مستوى لياقتك وهدفك.'], ARRAY['Use a neck harness designed for weightlifting. Securely attach a small weight plate to the harness chain.','Position a workout bench at a 45-degree incline. Sit on the bench and lean back so your upper back is supported while your head extends beyond the edge.','Place the neck harness on your head, ensuring it is centered. Let your head hang slightly back in a neutral position.','Flex your neck forward, bringing your chin toward your chest in a slow and controlled motion. Pause briefly at the top of the movement.','Slowly return your head to the starting position, resisting the weight as you lower.','Perform 2-4 sets of 8-15 repetitions depending on your fitness level and goals.'], ARRAY['neck'], ARRAY['stabilizing neck muscles'], NULL),
  ('هز الكتف جيتلسون', 'Gittleson Shrug', 'shoulders', 'dumbbell', 'اجلس على بنش أو كرسي وبيدك دمبل واحد. أمسك بحافة البنش خلف وركك مباشرة بيدك الحرة. اترك كتف الجانب المُحمّل يتدلى للأسفل بأقصى ما يمكن. ارفع كتفك نحو أذنك، مع التركيز على انقباض عضلة الترابيزيوس العلوية. نفّذ العدد المطلوب من التكرارات على جانب واحد ثم بدّل إلى الجانب الآخر.', 'Sit on a bench or chair with a dumbbell in one hand. Grab the bottom of the bench just behind your hip with your free hand. Allow your loaded side shoulder to drop down as far as possible. Elevate your shoulder towards your ear, emphasizing the contraction of the upper trapezius muscles. Perform the desired number of repetitions on one side before switching to the other.', 'https://fitnessprogramer.com/wp-content/uploads/2022/01/Dumbbell-Seated-Gittleson-Shrug.gif', ARRAY['اجلس على بنش أو كرسي وبيدك دمبل واحد.','أمسك بحافة البنش خلف وركك مباشرة بيدك الحرة.','اترك كتف الجانب المُحمّل يتدلى للأسفل بأقصى ما يمكن.','ارفع كتفك نحو أذنك، مع التركيز على انقباض عضلة الترابيزيوس العلوية.','نفّذ العدد المطلوب من التكرارات على جانب واحد ثم بدّل إلى الجانب الآخر.'], ARRAY['Sit on a bench or chair with a dumbbell in one hand.','Grab the bottom of the bench just behind your hip with your free hand.','Allow your loaded side shoulder to drop down as far as possible.','Elevate your shoulder towards your ear, emphasizing the contraction of the upper trapezius muscles.','Perform the desired number of repetitions on one side before switching to the other.'], ARRAY['neck','trapezius upper'], ARRAY['trapezius middle','sternocleidomastoid','levator scapulae'], 'advanced'),
  ('تمديد الرقبة القُطري', 'Diagonal Neck Stretch', 'shoulders', 'none', 'أدر رقبتك قُطريًا نحو الجانب الأيمن بزاوية 45 درجة. أميل رأسك ببطء نحو صدرك مع الحفاظ على الدوران الجانبي. يجب أن تشعر بشدّ خفيف في جانب ومؤخرة الرقبة. حافظ على هذا الوضع لمدة 15-30 ثانية مع التنفس بثبات وهدوء. أعد رأسك ببطء إلى الوضع المحايد وكرر التمديد على الجانب الآخر. استهدف 2-4 تكرارات لكل جانب.', 'Turn your neck diagonally towards the right side at a 45-degree angle. Slowly tilt your head towards your chest while maintaining lateral rotation. You should feel a slight stretch on the side and back of your neck. Hold this position for 15-30 seconds while maintaining steady and relaxed breathing. Slowly return your head to the neutral position and repeat the stretch on the other side. Aim for 2-4 repetitions per side.', NULL, ARRAY['أدر رقبتك قُطريًا نحو الجانب الأيمن بزاوية 45 درجة.','أميل رأسك ببطء نحو صدرك مع الحفاظ على الدوران الجانبي.','يجب أن تشعر بشدّ خفيف في جانب ومؤخرة الرقبة.','حافظ على هذا الوضع لمدة 15-30 ثانية مع التنفس بثبات وهدوء.','أعد رأسك ببطء إلى الوضع المحايد وكرر التمديد على الجانب الآخر.','استهدف 2-4 تكرارات لكل جانب.'], ARRAY['Turn your neck diagonally towards the right side at a 45-degree angle.','Slowly tilt your head towards your chest while maintaining lateral rotation.','You should feel a slight stretch on the side and back of your neck.','Hold this position for 15-30 seconds while maintaining steady and relaxed breathing.','Slowly return your head to the neutral position and repeat the stretch on the other side.','Aim for 2-4 repetitions per side.'], ARRAY['neck'], ARRAY['levator scapulae','longissimus capitis','longissimus cervicis','semispinalis capitis','semispinalis cervicis','spinalis cervicis','spinalis capitis','splenius capitis','sternocleidomastoid','trapezius'], 'beginner'),
  ('تمديد دوران الرقبة', 'Neck Rotation Stretch', 'shoulders', 'none', 'أدر رأسك ببطء إلى جانب واحد، محاولًا تقريب أذنك من كتفك. حافظ على شدّ مريح؛ تجنب إجبار رأسك على وضع متطرف. يجب أن تشعر بشدّ لطيف على طول جانب رقبتك. حافظ على هذا الوضع لمدة 15-30 ثانية. أعد رأسك ببطء إلى وضع المنتصف وكرر التمديد على الجانب الآخر. استهدف 2-4 تكرارات لكل جانب.', 'Slowly turn your head to one side, aiming to bring your ear closer to your shoulder. Maintain a comfortable stretch; avoid forcing your head to an extreme position. You should feel a gentle pull along the side of your neck. Maintain this position for 15-30 seconds. Slowly return your head to the center position and repeat the stretch on the other side. Aim for 2-4 repetitions on each side.', 'https://fitnessprogramer.com/wp-content/uploads/2021/07/Rotating-Neck-Stretch.gif', ARRAY['أدر رأسك ببطء إلى جانب واحد، محاولًا تقريب أذنك من كتفك.','حافظ على شدّ مريح؛ تجنب إجبار رأسك على وضع متطرف.','يجب أن تشعر بشدّ لطيف على طول جانب رقبتك. حافظ على هذا الوضع لمدة 15-30 ثانية.','أعد رأسك ببطء إلى وضع المنتصف وكرر التمديد على الجانب الآخر.','استهدف 2-4 تكرارات لكل جانب.'], ARRAY['Slowly turn your head to one side, aiming to bring your ear closer to your shoulder.','Maintain a comfortable stretch; avoid forcing your head to an extreme position.','You should feel a gentle pull along the side of your neck. Maintain this position for 15-30 seconds.','Slowly return your head to the center position and repeat the stretch on the other side.','Aim for 2-4 repetitions on each side.'], ARRAY['neck'], ARRAY['scalene anterior','sternocleidomastoid','splenius capitis','splenius cervicis','rectus capitis','semispinalis capitis','longus capitis','longus colli'], 'beginner'),
  ('تمديد ثني الرقبة', 'Neck Flexion Stretch', 'shoulders', 'none', 'أميل رأسك للأمام ببطء، مقربًا ذقنك من صدرك، مع ترك وزن رأسك يخلق شدًا لطيفًا في مؤخرة رقبتك. حافظ على الوضع بلطف لمدة 5-10 ثوانٍ. عد إلى وضع البداية. كرر التسلسل 3-5 مرات.', 'Slowly tilt your head forward, bringing your chin toward your chest and allowing the weight of your head to create a gentle stretch along the back of your neck. Hold gently for 5-10 seconds. Return to the starting position. Repeat the sequence 3-5 times.', NULL, ARRAY['أميل رأسك للأمام ببطء، مقربًا ذقنك من صدرك، مع ترك وزن رأسك يخلق شدًا لطيفًا في مؤخرة رقبتك.','حافظ على الوضع بلطف لمدة 5-10 ثوانٍ.','عد إلى وضع البداية.','كرر التسلسل 3-5 مرات.'], ARRAY['Slowly tilt your head forward, bringing your chin toward your chest and allowing the weight of your head to create a gentle stretch along the back of your neck.','Hold gently for 5-10 seconds.','Return to the starting position.','Repeat the sequence 3-5 times.'], ARRAY['neck'], ARRAY['semispinalis capitis','spinalis capitis','spinalis cervicis','longissimus capitis','levator scapulae','splenius capitis','splenius cervicis','sternothyroid','trapezius'], 'beginner'),
  ('تمديد مد الرقبة', 'Neck Extension Stretch', 'shoulders', 'none', 'اجلس بشكل مستقيم وكتفاك مرتاحتان. أميل رأسك للخلف ببطء، ناظرًا للأعلى. حافظ على الوضع لثوانٍ قليلة، ثم عد ببطء إلى وضع البداية. كرر عدة مرات.', 'Sit tall with your shoulders relaxed. Slowly tilt your head back, looking upwards. Hold for a few seconds, then slowly return to the starting position. Repeat a few times.', NULL, ARRAY['اجلس بشكل مستقيم وكتفاك مرتاحتان.','أميل رأسك للخلف ببطء، ناظرًا للأعلى.','حافظ على الوضع لثوانٍ قليلة، ثم عد ببطء إلى وضع البداية.','كرر عدة مرات.'], ARRAY['Sit tall with your shoulders relaxed.','Slowly tilt your head back, looking upwards.','Hold for a few seconds, then slowly return to the starting position.','Repeat a few times.'], ARRAY['neck'], ARRAY['semispinalis capitis','platysma','longus colli','omohyoid','splenius','sternocleidomastoid','sternothyroid','scalene'], 'beginner'),
  ('تمديد الرقبة الجانبي', 'Side Neck Stretch', 'shoulders', 'none', 'ثبّت رأسك في خط الوسط. انحن برأسك بلطف نحو الجانب الأيسر لتقريب أذنك من كتفك. اثنِ رقبتك بأقصى ما يمكن دون ألم. حافظ على الوضع لمدة 10-20 ثانية. أعد رأسك إلى وضعه الأصلي ونفّذ الانحناء الجانبي على الجانب الآخر.', 'Hold the head in the midline. Gently flex the head to the left side to let the ears touch the shoulders. Flex the neck as far as it can go without causing pain. Hold the position for 10-20 seconds. Bring back the head to its original position and do the lateral flexion on the opposite side.', 'https://fitnessprogramer.com/wp-content/uploads/2021/06/Side-Neck-Stretch.gif', ARRAY['ثبّت رأسك في خط الوسط.','انحن برأسك بلطف نحو الجانب الأيسر لتقريب أذنك من كتفك.','اثنِ رقبتك بأقصى ما يمكن دون ألم.','حافظ على الوضع لمدة 10-20 ثانية.','أعد رأسك إلى وضعه الأصلي ونفّذ الانحناء الجانبي على الجانب الآخر.'], ARRAY['Hold the head in the midline.','Gently flex the head to the left side to let the ears touch the shoulders.','Flex the neck as far as it can go without causing pain.','Hold the position for 10-20 seconds.','Bring back the head in its original position and do the lateral flexion on the opposite side.'], ARRAY['neck'], ARRAY['levator scapulae','middle scalene','anterior scalene','sternocleidomastoid','omohyoid','trapezius'], NULL),
  ('تمديد الرقبة الجانبي بالدفع', 'Side Push Neck Stretch', 'shoulders', 'none', 'حافظ على الوضع لمدة 10-20 ثانية. عد إلى وضع البداية. كرر 3 إلى 4 مرات.', 'Hold the position for 10-20 seconds. Return to starting position. Repeat 3 to 4 times.', 'https://fitnessprogramer.com/wp-content/uploads/2021/06/Side-Push-Neck-Stretch.gif', ARRAY['حافظ على الوضع لمدة 10-20 ثانية.','عد إلى وضع البداية.','كرر 3 إلى 4 مرات.'], ARRAY['Hold the position for 10-20 seconds.','Return to starting position.','Repeat 3 to 4 times.'], ARRAY['neck'], ARRAY['levator scapulae','middle scalene','anterior scalene','sternocleidomastoid','omohyoid','trapezius'], 'beginner'),
  ('تمديد الرقبة للأمام والخلف', 'Front and Back Neck Stretch', 'shoulders', 'none', 'حافظ على وضع رأسك محايدًا في جميع الأوقات. أميل رأسك للخلف مباشرة بأقصى ما يمكن. شابك أصابعك وضع يديك على جبهتك. حاول ببطء تحريك رأسك للأمام كما لو كنت تحاول لمس صدرك بذقنك، مع مقاومة الحركة بيديك وذراعيك. حافظ على الوضع لمدة 10-15 ثانية ثم عد إلى وضع البداية. اعكس الحركة بثني رأسك للأمام مع وضع اليدين خلف الرأس للدعم، مكملًا 3-4 تكرارات إجمالًا.', 'Keep your head in a neutral position at all times. Tilt your head straight back as far as you can. Interlock your fingers and place your hands on your forehead. Slowly try to bring your head forward as though trying to touch your chest with your chin, and resist with your hands and arms. Hold the position for 10-15 seconds and return to the starting position. Reverse the movement by bending your head forward with hands positioned behind your head for support, completing 3-4 repetitions total.', 'https://fitnessprogramer.com/wp-content/uploads/2021/06/Front-and-Back-Neck-Stretch.gif', ARRAY['حافظ على وضع رأسك محايدًا في جميع الأوقات.','أميل رأسك للخلف مباشرة بأقصى ما يمكن.','شابك أصابعك وضع يديك على جبهتك.','حاول ببطء تحريك رأسك للأمام كما لو كنت تحاول لمس صدرك بذقنك، مع مقاومة الحركة بيديك وذراعيك.','حافظ على الوضع لمدة 10-15 ثانية ثم عد إلى وضع البداية.','اعكس الحركة بثني رأسك للأمام مع وضع اليدين خلف الرأس للدعم، مكملًا 3-4 تكرارات إجمالًا.'], ARRAY['Keep your head in a neutral position at all times.','Tilt your head straight back as far as you can.','Interlock your fingers and place your hands on your forehead.','Slowly try to bring your head forward as though trying to touch your chest with your chin, and resist with your hands and arms.','Hold the position for 10-15 seconds and return to the starting position.','Reverse the movement by bending your head forward with hands positioned behind your head for support, completing 3-4 repetitions total.'], ARRAY['neck'], ARRAY['semispinalis capitis','splenius capitis','longissimus capitis','platysma','sternothyroid','omohyoid','sternocleidomastoid','scalene','trapezius','splenius cervicis'], NULL),
  ('سحب الذقن للخلف', 'Chin Tuck', 'shoulders', 'none', 'انظر مباشرة أمامك. ضع إصبعين على ذقنك. اسحب ذقنك للداخل قليلًا وحرّك رأسك للخلف. حافظ على الوضع لمدة 3-5 ثوانٍ. حرر الوضع وكرر 10 مرات.', 'Look straight ahead. Place two fingers on your chin. Slightly tuck your chin and move your head back. Hold for 3-5 seconds. Release and repeat 10 times.', 'https://fitnessprogramer.com/wp-content/uploads/2021/06/Chin-Tuck.gif', ARRAY['انظر مباشرة أمامك.','ضع إصبعين على ذقنك.','اسحب ذقنك للداخل قليلًا وحرّك رأسك للخلف.','حافظ على الوضع لمدة 3-5 ثوانٍ.','حرر الوضع وكرر 10 مرات.'], ARRAY['Look straight ahead.','Place two fingers on your chin.','Slightly tuck your chin and move your head back.','Hold for 3-5 seconds.','Release and repeat 10 times.'], ARRAY['neck'], ARRAY['scalene','semispinalis capitis','splenius capitis','longissimus capitis','sternothyroid','omohyoid','sternocleidomastoid','splenius cervicis'], NULL),
  ('مد الرقبة أثناء الاستلقاء على البطن', 'Prone Cervical Extension', 'shoulders', 'none', 'استلق على بطنك بحيث تتجاوز رقبتك حافة البنش أو السجادة. مدّ رقبتك ببطء للأعلى، رافعًا رأسك بأقصى ما يمكن بشكل مريح. حافظ على الوضع لحظة في الأعلى. أنزل رأسك للأسفل بتحكم وكرر للعدد المطلوب من التكرارات.', 'Lie face down with your neck extending off the edge of a bench or mat. Slowly extend your neck upward, lifting your head as high as comfortably possible. Hold briefly at the top. Lower your head back down with control and repeat for the desired number of repetitions.', 'https://fitnessprogramer.com/wp-content/uploads/2022/02/Prone-Cervical-Extension.gif', ARRAY['استلق على بطنك بحيث تتجاوز رقبتك حافة البنش أو السجادة.','مدّ رقبتك ببطء للأعلى، رافعًا رأسك بأقصى ما يمكن بشكل مريح.','حافظ على الوضع لحظة في الأعلى.','أنزل رأسك للأسفل بتحكم وكرر للعدد المطلوب من التكرارات.'], ARRAY['Lie face down with your neck extending off the edge of a bench or mat.','Slowly extend your neck upward, lifting your head as high as comfortably possible.','Hold briefly at the top.','Lower your head back down with control and repeat for the desired number of repetitions.'], ARRAY['neck'], ARRAY[]::text[], 'beginner'),
  ('تمديد الرقبة أثناء الجلوس على الركبتين', 'Kneeling Neck Stretch', 'shoulders', 'none', 'اجلس على ركبتيك على الأرض وأميل رأسك بلطف نحو جانب واحد. حافظ على التمديد لمدة 15-30 ثانية مع التنفس بثبات. عد إلى المنتصف وكرر على الجانب الآخر. يخفف هذا التمرين توتر عضلات الرقبة والظهر العلوي ويحسّن مرونة الرقبة.', 'Kneel on the floor and gently tilt your head to one side. Hold the stretch for 15-30 seconds, breathing steadily. Return to the center and repeat on the other side. This exercise relieves tension in the neck and upper back muscles and can improve flexibility in the neck.', 'https://fitnessprogramer.com/wp-content/uploads/2022/02/Kneeling-Neck-Stretch.gif', ARRAY['اجلس على ركبتيك على الأرض وأميل رأسك بلطف نحو جانب واحد.','حافظ على التمديد لمدة 15-30 ثانية مع التنفس بثبات.','عد إلى المنتصف وكرر على الجانب الآخر.'], ARRAY['Kneel on the floor and gently tilt your head to one side.','Hold the stretch for 15-30 seconds, breathing steadily.','Return to the center and repeat on the other side.'], ARRAY['neck'], ARRAY['splenius','trapezius upper','levator scapulae','sternocleidomastoid'], 'beginner'),
  ('مد الرقبة بالوزن بحزام الرأس', 'Weighted Neck Harness Extension', 'shoulders', 'none', 'ثبّت حزام الرأس على رأسك ورَكّب عليه قرص وزن. اتخذ وضعية تسمح لرأسك بالحركة بحرية ضد المقاومة. مدّ رقبتك ببطء للخلف ضد الوزن، ثم عد بتحكم. كرر للعدد المطلوب من التكرارات.', 'Strap the neck harness onto your head and attach a weight plate. Position yourself so your head can move freely against the resistance. Slowly extend your neck backward against the weight, then return with control. Repeat for the desired number of repetitions.', 'https://fitnessprogramer.com/wp-content/uploads/2022/02/Weighted-Neck-Harness-Extension.gif', ARRAY['ثبّت حزام الرأس على رأسك ورَكّب عليه قرص وزن.','اتخذ وضعية تسمح لرأسك بالحركة بحرية ضد المقاومة.','مدّ رقبتك ببطء للخلف ضد الوزن، ثم عد بتحكم.','كرر للعدد المطلوب من التكرارات.'], ARRAY['Strap the neck harness onto your head and attach a weight plate.','Position yourself so your head can move freely against the resistance.','Slowly extend your neck backward against the weight, then return with control.','Repeat for the desired number of repetitions.'], ARRAY['neck'], ARRAY[]::text[], NULL),
  ('ثني الرقبة بالوزن أثناء الاستلقاء', 'Lying Weighted Neck Flexion', 'shoulders', 'dumbbell', 'استلق على ظهرك على بنش بحيث تتجاوز رأسك نهايته، وامسك قرص وزن أو دمبل على جبهتك. اثنِ رقبتك ببطء للأمام، رافعًا رأسك ضد المقاومة. أنزل رأسك بتحكم وكرر للعدد المطلوب من التكرارات.', 'Lie on your back on a bench with your head extending off the end, holding a weight plate or dumbbell against your forehead. Slowly flex your neck forward, lifting your head against the resistance. Lower back down with control and repeat for the desired number of repetitions.', 'https://fitnessprogramer.com/wp-content/uploads/2022/02/Lying-Weighted-Neck-Flexion.gif', ARRAY['استلق على ظهرك على بنش بحيث تتجاوز رأسك نهايته، وامسك قرص وزن أو دمبل على جبهتك.','اثنِ رقبتك ببطء للأمام، رافعًا رأسك ضد المقاومة.','أنزل رأسك بتحكم وكرر للعدد المطلوب من التكرارات.'], ARRAY['Lie on your back on a bench with your head extending off the end, holding a weight plate or dumbbell against your forehead.','Slowly flex your neck forward, lifting your head against the resistance.','Lower back down with control and repeat for the desired number of repetitions.'], ARRAY['neck'], ARRAY[]::text[], NULL),
  ('مد الرقبة بالوزن أثناء الاستلقاء', 'Lying Weighted Neck Extension', 'shoulders', 'dumbbell', 'استلق على وجهك على بنش بحيث تتجاوز رأسك نهايته، وامسك قرص وزن أو دمبل على مؤخرة رأسك. مدّ رقبتك ببطء للخلف، رافعًا رأسك ضد المقاومة. أنزل رأسك بتحكم وكرر للعدد المطلوب من التكرارات.', 'Lie face down on a bench with your head extending off the end, holding a weight plate or dumbbell against the back of your head. Slowly extend your neck backward, lifting your head against the resistance. Lower back down with control and repeat for the desired number of repetitions.', 'https://fitnessprogramer.com/wp-content/uploads/2022/02/Lying-Weighted-Neck-Extension.gif', ARRAY['استلق على وجهك على بنش بحيث تتجاوز رأسك نهايته، وامسك قرص وزن أو دمبل على مؤخرة رأسك.','مدّ رقبتك ببطء للخلف، رافعًا رأسك ضد المقاومة.','أنزل رأسك بتحكم وكرر للعدد المطلوب من التكرارات.'], ARRAY['Lie face down on a bench with your head extending off the end, holding a weight plate or dumbbell against the back of your head.','Slowly extend your neck backward, lifting your head against the resistance.','Lower back down with control and repeat for the desired number of repetitions.'], ARRAY['neck'], ARRAY[]::text[], NULL),
  ('ثني الرقبة الجانبي الأيمن بجهاز الرافعة (بالأقراص)', 'Lever Neck Right Side Flexion (plate loaded)', 'shoulders', 'machine', 'اجلس على جهاز الرافعة للرقبة وضع الوسادة على الجانب الأيمن من رأسك. اثنِ رقبتك ببطء نحو اليمين ضد المقاومة. عد بتحكم إلى وضع البداية وكرر للعدد المطلوب من التكرارات.', 'Sit at the lever neck machine and position the pad against the right side of your head. Slowly flex your neck to the right against the resistance. Return with control to the starting position and repeat for the desired number of repetitions.', 'https://fitnessprogramer.com/wp-content/uploads/2022/02/Lever-Neck-Right-Side-Flexion-plate-loaded.gif', ARRAY['اجلس على جهاز الرافعة للرقبة وضع الوسادة على الجانب الأيمن من رأسك.','اثنِ رقبتك ببطء نحو اليمين ضد المقاومة.','عد بتحكم إلى وضع البداية وكرر للعدد المطلوب من التكرارات.'], ARRAY['Sit at the lever neck machine and position the pad against the right side of your head.','Slowly flex your neck to the right against the resistance.','Return with control to the starting position and repeat for the desired number of repetitions.'], ARRAY['neck'], ARRAY[]::text[], NULL),
  ('مد الرقبة بجهاز الرافعة (بالأقراص)', 'Lever Neck Extension (plate loaded)', 'shoulders', 'machine', 'اجلس على جهاز الرافعة للرقبة وضع الوسادة على مؤخرة رأسك. مدّ رقبتك ببطء للخلف ضد المقاومة. عد بتحكم إلى وضع البداية وكرر للعدد المطلوب من التكرارات.', 'Sit at the lever neck machine and position the pad against the back of your head. Slowly extend your neck backward against the resistance. Return with control to the starting position and repeat for the desired number of repetitions.', 'https://fitnessprogramer.com/wp-content/uploads/2022/02/Lever-Neck-Extension-plate-loaded.gif', ARRAY['اجلس على جهاز الرافعة للرقبة وضع الوسادة على مؤخرة رأسك.','مدّ رقبتك ببطء للخلف ضد المقاومة.','عد بتحكم إلى وضع البداية وكرر للعدد المطلوب من التكرارات.'], ARRAY['Sit at the lever neck machine and position the pad against the back of your head.','Slowly extend your neck backward against the resistance.','Return with control to the starting position and repeat for the desired number of repetitions.'], ARRAY['neck'], ARRAY[]::text[], NULL),
  ('ثني الرقبة بالكابل أثناء الجلوس بحزام الرأس', 'Cable Seated Neck Flexion with Head Harness', 'shoulders', 'cable', 'اجلس بحيث تكون بعيدًا عن بكرة الكابل المنخفضة مع حزام الرأس مثبّت على الكابل. اثنِ رقبتك ببطء للأمام ضد المقاومة. عد بتحكم إلى وضع البداية وكرر للعدد المطلوب من التكرارات.', 'Sit facing away from a low cable pulley with the head harness attached to the cable. Slowly flex your neck forward against the resistance. Return with control to the starting position and repeat for the desired number of repetitions.', 'https://fitnessprogramer.com/wp-content/uploads/2022/02/Cable-Seated-Neck-Flexion-with-head-harness.gif', ARRAY['اجلس بحيث تكون بعيدًا عن بكرة الكابل المنخفضة مع حزام الرأس مثبّت على الكابل.','اثنِ رقبتك ببطء للأمام ضد المقاومة.','عد بتحكم إلى وضع البداية وكرر للعدد المطلوب من التكرارات.'], ARRAY['Sit facing away from a low cable pulley with the head harness attached to the cable.','Slowly flex your neck forward against the resistance.','Return with control to the starting position and repeat for the desired number of repetitions.'], ARRAY['neck'], ARRAY[]::text[], NULL),
  ('مد الرقبة بالكابل أثناء الجلوس بحزام الرأس', 'Cable Seated Neck Extension with Head Harness', 'shoulders', 'cable', 'اجلس بمواجهة بكرة الكابل المنخفضة مع حزام الرأس مثبّت على الكابل خلفك. مدّ رقبتك ببطء للخلف ضد المقاومة. عد بتحكم إلى وضع البداية وكرر للعدد المطلوب من التكرارات.', 'Sit facing a low cable pulley with the head harness attached to the cable behind you. Slowly extend your neck backward against the resistance. Return with control to the starting position and repeat for the desired number of repetitions.', 'https://fitnessprogramer.com/wp-content/uploads/2022/02/Cable-Seated-Neck-Extension-with-head-harness.gif', ARRAY['اجلس بمواجهة بكرة الكابل المنخفضة مع حزام الرأس مثبّت على الكابل خلفك.','مدّ رقبتك ببطء للخلف ضد المقاومة.','عد بتحكم إلى وضع البداية وكرر للعدد المطلوب من التكرارات.'], ARRAY['Sit facing a low cable pulley with the head harness attached to the cable behind you.','Slowly extend your neck backward against the resistance.','Return with control to the starting position and repeat for the desired number of repetitions.'], ARRAY['neck'], ARRAY[]::text[], NULL),
  ('تمديد أبو الهول', 'Sphinx Stretch', 'back', 'none', 'اتخذ وضعية أبو الهول، مستلقيًا على بطنك مرتكزًا على ساعديك. حافظ على الوضع لعدد يصل إلى 10 أنفاس. ازفر بينما تُنزل جذعك وصدرك ورأسك ببطء نحو الأرض.', 'Assume the sphinx pose position, lying on your stomach propped up on your forearms. Hold for up to 10 breaths. Exhale while slowly lowering your torso, chest, and head to the floor.', 'https://fitnessprogramer.com/wp-content/uploads/2021/05/Sphinx-Stretch.gif', ARRAY['اتخذ وضعية أبو الهول، مستلقيًا على بطنك مرتكزًا على ساعديك.','حافظ على الوضع لعدد يصل إلى 10 أنفاس.','ازفر بينما تُنزل جذعك وصدرك ورأسك ببطء نحو الأرض.'], ARRAY['Assume the sphinx pose position, lying on your stomach propped up on your forearms.','Hold for up to 10 breaths.','Exhale while slowly lowering your torso, chest, and head to the floor.'], ARRAY['erector spinae','neck'], ARRAY['trapezius','abs','chest'], 'beginner'),
  ('فرط تمديد الظهر على الأرض', 'Floor Hyperextension', 'back', 'none', 'استلق على وجهك ورجلاك متلاصقتان. ضع يديك بجانب رأسك، مع إبقاء كتفيك مرتاحتين وجذعك مشدودًا. اشهق. ازفر وأنت ترفع جزء جسمك العلوي عن الأرض، منفذًا الحركة ببطء ومتحكمًا بها عبر عضلات الجذع. اشهق، وحافظ على الوضع لحظة في الأعلى، ثم أنزل جسمك ببطء ولطف إلى وضع البداية.', 'Lie face down with your legs together. Place your hands by the side of your head, keeping your shoulders relaxed and your core active. Breathe in. Exhale as you lift your upper body off the floor, performing the movement slowly and controlling it with your core. Breathe in, hold briefly at the top, then slowly and gently lower yourself back to the start position.', 'https://fitnessprogramer.com/wp-content/uploads/2021/04/Floor-Hyperextension-1.gif', ARRAY['استلق على وجهك ورجلاك متلاصقتان. ضع يديك بجانب رأسك، مع إبقاء كتفيك مرتاحتين وجذعك مشدودًا. اشهق.','ازفر وأنت ترفع جزء جسمك العلوي عن الأرض. نفّذ الحركة ببطء متحكمًا بها عبر عضلات الجذع.','اشهق، وحافظ على الوضع لحظة في الأعلى مع إبقاء الجذع مشدودًا، ثم أنزل جسمك ببطء ولطف إلى وضع البداية.'], ARRAY['Lie face down with your legs together. Place your hands by the side of your head, keeping your shoulders relaxed and your core active. Breathe in.','Exhale as you lift your upper body off the floor. Perform the movement slowly, controlling it with your core.','Breathe in, hold briefly at the top of the movement, maintaining an active core, then slowly and gently lower yourself back to the start position.'], ARRAY['erector spinae','neck'], ARRAY['trapezius','splenius','abs'], 'beginner'),
  ('تمديد الكوبرا للبطن (بوجانغاسانا)', 'Bhujangasana | Cobra Abdominal Stretch', 'core', 'none', 'استلق على وجهك على سجادة مع وضع يديك بشكل مسطح تحت كتفيك. اضغط ببطء على يديك وفرد ذراعيك، رافعًا صدرك ورأسك عن الأرض. حافظ على مرفقيك قريبين من جسمك واستمر في هذا الوضع لثوانٍ قليلة، متنفسًا بعمق. عد إلى وضع البداية وكرر عدة مرات.', 'Start by lying face-down on a mat with your hands placed flat under your shoulders. Slowly press into your hands and straighten your arms, lifting your chest and head off the ground. Keep your elbows close to your body and hold this position for a few seconds, breathing deeply. Release back down to the starting position and repeat several times.', 'https://fitnessprogramer.com/wp-content/uploads/2021/06/abdominal-stretch.gif', ARRAY['استلق على وجهك على سجادة مع وضع يديك بشكل مسطح تحت كتفيك.','اضغط ببطء على يديك وفرد ذراعيك، رافعًا صدرك ورأسك عن الأرض.','حافظ على مرفقيك قريبين من جسمك واستمر في هذا الوضع لثوانٍ قليلة، متنفسًا بعمق.','عد إلى وضع البداية. كرر عدة مرات.'], ARRAY['Start by lying face-down on a mat with your hands placed flat under your shoulders.','Slowly press into your hands and straighten your arms, lifting your chest and head off the ground.','Keep your elbows close to your body and hold this position for a few seconds, breathing deeply.','Release back down to the starting position. Repeat several times.'], ARRAY['abs','neck'], ARRAY['lower back','rectus abdominis'], 'beginner'),
  ('وضعية السمكة (ماتسياسانا)', 'Fish Pose', 'core', 'none', 'استلق على ظهرك مع فرد رجليك وترك ذراعيك بجانب جسمك. اسحب يديك بحيث تكون راحتاهما للأسفل تحت مقعدتك للدعم، وحافظ على تقارب مرفقيك وشدهما. اضغط بساعديك ومرفقيك لرفع صدرك العلوي نحو السقف، مع ترك رأسك يتدلى للخلف بلطف. تنفس بعمق واستمر في الوضع لمدة 15-30 ثانية. ازفر، وأنزل صدرك ببطء، وأعد رأسك إلى السجادة.', 'Lie on your back with legs extended and arms resting beside your body. Slide your hands palms-down underneath your buttocks for support, keeping elbows close together and engaged. Press through your forearms and elbows to lift your upper chest toward the ceiling, allowing your head to gently drop back. Breathe deeply and hold for 15 to 30 seconds. Exhale, slowly lower your chest, and bring your head back to the mat.', 'https://fitnessprogramer.com/wp-content/uploads/2022/02/Fish-Pose-Matsyasana.gif', ARRAY['استلق على ظهرك مع فرد رجليك وترك ذراعيك بجانب جسمك.','اسحب يديك بحيث تكون راحتاهما للأسفل تحت مقعدتك للدعم، وحافظ على تقارب مرفقيك وشدهما.','اضغط بساعديك ومرفقيك لرفع صدرك العلوي نحو السقف، مع ترك رأسك يتدلى للخلف بلطف.','تنفس بعمق واستمر في الوضع لمدة 15-30 ثانية (أو أطول للتمارين الاستشفائية).','ازفر، وأنزل صدرك ببطء، وأعد رأسك إلى السجادة. اسحب يديك من تحت وركيك.'], ARRAY['Lie on your back with legs extended and arms resting beside your body.','Slide your hands palms-down underneath your buttocks for support. Keep your elbows close together and engaged.','Press through your forearms and elbows to lift your upper chest toward the ceiling. Allow your head to gently drop back.','Breathe deeply and hold for 15 to 30 seconds (or longer for restorative practice).','Exhale, slowly lower your chest, and bring your head back to the mat. Remove your hands from under your hips.'], ARRAY['abs','chest','neck'], ARRAY['pectoralis major','neck extensors','intercostals','rectus abdominis','upper back','erector spinae'], 'beginner'),
  ('تمرين السوبرمان', 'Superman', 'back', 'none', 'استلق على وجهك على سجادة مع مد ذراعيك أمامك ورجليك خلفك. ارفع ذراعيك وصدرك ورجليك عن الأرض في نفس الوقت، مع شد عضلات أسفل الظهر والمقعدة. حافظ على وضع الأعلى لحظة قصيرة، ثم أنزل جسمك بتحكم. يقوّي هذا التمرين عضلات مقيم الفقار الداعمة للعمود الفقري ويحسّن وضعية الجسم.', 'Lie face down on a mat with your arms extended in front of you and legs extended behind you. Simultaneously lift your arms, chest, and legs off the floor, engaging your lower back and glutes. Hold the top position briefly, then lower back down with control. This exercise strengthens the erector spinae muscles that support the spine and can improve posture.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Superman-exercise.gif', ARRAY['استلق على وجهك على سجادة مع مد ذراعيك أمامك ورجليك خلفك.','ارفع ذراعيك وصدرك ورجليك عن الأرض في نفس الوقت، مع شد عضلات أسفل الظهر والمقعدة.','حافظ على وضع الأعلى لحظة قصيرة.','أنزل جسمك بتحكم وكرر للعدد المطلوب من التكرارات.'], ARRAY['Lie face down on a mat with your arms extended in front of you and legs extended behind you.','Simultaneously lift your arms, chest, and legs off the floor, engaging your lower back and glutes.','Hold the top position briefly.','Lower back down with control and repeat for the desired number of repetitions.'], ARRAY['erector spinae','neck'], ARRAY['abs','hamstrings','glutes','trapezius','deltoid','splenius'], 'beginner'),
  ('ضغط الكتف بالبار جلوسًا', 'Seated Barbell Shoulder Press', 'shoulders', 'barbell', 'اجلس بشكل مستقيم على بنش مسطح، وقدماك أوسع من الوركين قليلًا. اضبط البار عند مستوى الكتف على الحامل وأمسكه بقبضة أوسع قليلًا من عرض الكتفين. حرر البار وأنزله إلى مستوى الكتف مع وضع مرفقيك أمام البار قليلًا. شد جذعك ومقعدتك للحفاظ على توازنك. اضغط بالبار للأعلى فوق رأسك، مع فرد ذراعيك دون الانحناء للخلف. أنزل البار بتحكم إلى مستوى كتفيك.', 'Sit upright on a flat bench, feet planted slightly wider than hip-width. Set the barbell at shoulder height on a rack and grip it slightly wider than shoulder-width. Unrack the bar to shoulder level with elbows slightly in front of the bar. Engage your core and glutes to maintain balance. Press the bar overhead, extending your arms without leaning backward. Lower the bar under control back to shoulder line.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Barbell-Shoulder-Press.gif', ARRAY['اجلس بشكل مستقيم على بنش مسطح، وقدماك مسطحتان على الأرض بعرض أوسع من الوركين قليلًا.','اضبط البار عند مستوى الكتف على الحامل وأمسكه بقبضة أوسع قليلًا من عرض الكتفين.','حرر البار من الحامل وأنزله إلى مستوى الكتف مع وضع مرفقيك أمام البار قليلًا.','شد جذعك ومقعدتك للحفاظ على توازنك دون مسند للظهر.','اضغط بالبار للأعلى فوق رأسك، مع فرد ذراعيك دون الانحناء للخلف.','أنزل البار بتحكم إلى مستوى صدرك العلوي أو كتفيك.'], ARRAY['Sit upright on a flat bench, keeping feet flat and planted slightly wider than hip-width.','Set the barbell at shoulder height on a rack and grip it slightly wider than shoulder-width.','Unrack the bar and bring it to shoulder level with elbows slightly in front of the bar.','Engage your core and glutes to maintain balance without a backrest.','Press the bar overhead, extending your arms without leaning backward.','Lower the bar under control back to your upper chest or shoulder line.'], ARRAY['anterior deltoid'], ARRAY['supraspinatus','triceps','lateral deltoid','trapezius','serratus anterior'], NULL),
  ('ضغط الكتف بالدمبل وقوفًا', 'Standing Dumbbell Shoulder Press', 'shoulders', 'dumbbell', 'قف بشكل مستقيم وقدماك بعرض الكتفين وركبتاك مثنيتان قليلًا. أمسك دمبل بكل يد عند مستوى الكتف وراحتا يديك متجهتان للأمام. شد جذعك وحافظ على صدرك مرفوعًا وعمودك الفقري في وضع محايد. اضغط بالدمبل للأعلى فوق رأسك، مع فرد ذراعيك دون تقويس ظهرك. أنزل الدمبل بتحكم إلى مستوى الكتف. كرر للعدد المطلوب من التكرارات.', 'Stand tall with feet shoulder-width apart and knees slightly bent. Hold a dumbbell in each hand at shoulder level, palms facing forward. Brace your core, keep chest up and spine neutral. Press the dumbbells overhead, extending your arms without arching your back. Lower the dumbbells under control to shoulder level. Repeat for desired reps.', NULL, ARRAY['قف بشكل مستقيم وقدماك بعرض الكتفين وركبتاك مثنيتان قليلًا.','أمسك دمبل بكل يد عند مستوى الكتف وراحتا يديك متجهتان للأمام.','شد جذعك وحافظ على صدرك مرفوعًا وعمودك الفقري في وضع محايد.','اضغط بالدمبل للأعلى فوق رأسك، مع فرد ذراعيك دون تقويس ظهرك.','أنزل الدمبل بتحكم إلى مستوى الكتف لإكمال تكرار واحد.','كرر للعدد المطلوب من التكرارات مع الحفاظ على وضعية ثابتة طوال المجموعة.'], ARRAY['Stand tall with feet shoulder-width apart and knees slightly bent.','Hold a dumbbell in each hand at shoulder level with your palms facing forward.','Brace your core and keep your chest up and spine neutral.','Press the dumbbells overhead, extending your arms without arching your back.','Lower the dumbbells under control to shoulder level to complete one rep.','Repeat for desired reps, maintaining steady posture throughout the set.'], ARRAY['anterior deltoid'], ARRAY['lateral deltoid','supraspinatus','triceps','trapezius','serratus anterior','pectoralis major clavicular','levator scapulae','biceps brachii'], NULL),
  ('رفرفة الكتف الجانبية بالدمبل', 'Dumbbell Lateral Raise', 'shoulders', 'dumbbell', 'قف بشكل مستقيم وقدماك بعرض الكتفين، وأمسك الدمبل بجانب جسمك وراحتا يديك متجهتان للداخل. شد جذعك واثنِ ركبتيك قليلًا. ارفع الدمبل للجانبين مع ثني خفيف في مرفقيك حتى تصل ذراعاك لمستوى الكتف. أنزل الأوزان ببطء إلى وضع البداية. استمر لمدة 10-12 تكرارًا.', 'Stand upright with feet shoulder-width apart, holding dumbbells at your sides with palms facing inward. Engage your core and slightly bend your knees. Lift the dumbbells out to your sides with a slight bend in your elbows until arms reach shoulder level. Lower slowly back to the starting position. Continue for 10-12 reps.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Dumbbell-Lateral-Raise.gif', ARRAY['قف بشكل مستقيم وقدماك بعرض الكتفين، وأمسك الدمبل بجانب جسمك وراحتا يديك متجهتان للداخل.','شد عضلات جذعك واثنِ ركبتيك قليلًا للحفاظ على الثبات.','ارفع الدمبل للجانبين مع الحفاظ على ثني خفيف في مرفقيك واستقامة معصميك، حتى تصل ذراعاك لمستوى الكتف موازيتين للأرض.','أنزل الأوزان ببطء وبسلاسة إلى وضع البداية مع الحفاظ على التحكم والشد في كتفيك.','استمر للعدد المطلوب من التكرارات، عادة 10-12 تكرارًا.'], ARRAY['Stand upright with feet shoulder-width apart, holding dumbbells at your sides with palms facing inward.','Engage your core muscles and slightly bend your knees to maintain stability.','Lift the dumbbells out to your sides, keeping a slight bend in your elbows and wrists straight. Raise the dumbbells until your arms reach shoulder level, parallel to the floor.','Lower the weights slowly and smoothly back to the starting position while maintaining control and tension in your shoulders.','Continue for the desired number of repetitions, typically 10-12 reps.'], ARRAY['lateral deltoid'], ARRAY['anterior deltoid','posterior deltoid','supraspinatus','serratus anterior','trapezius'], NULL),
  ('ضغط الكتف بالدمبل', 'Dumbbell Shoulder Press', 'shoulders', 'dumbbell', 'اجلس على بنش بمسند للظهر أو قف وقدماك بعرض الوركين. أمسك دمبل بكل يد عند مستوى الكتف وراحتا يديك متجهتان للأمام. شد جذعك، وحافظ على عمودك الفقري محايدًا، واسحب لوحي كتفك للخلف بخفة. اضغط بالدمبل للأعلى حتى تصبح ذراعاك مفرودتين دون قفل مرفقيك. أنزل الدمبل ببطء إلى مستوى الكتف.', 'Sit on a bench with back support or stand with feet hip-width apart. Hold a dumbbell in each hand at shoulder height, palms facing forward. Engage your core, keep spine neutral, retract shoulder blades lightly. Press the dumbbells upward until arms are fully extended without locking elbows. Slowly lower back to shoulder height.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Dumbbell-Shoulder-Press.gif', ARRAY['اجلس على بنش بمسند للظهر أو قف وقدماك بعرض الوركين. أمسك دمبل بكل يد عند مستوى الكتف وراحتا يديك متجهتان للأمام أو للداخل قليلًا.','شد جذعك، وحافظ على عمودك الفقري محايدًا، واسحب لوحي كتفك للخلف بخفة.','اضغط بالدمبل للأعلى وقليلًا للداخل حتى تصبح ذراعاك مفرودتين تمامًا دون قفل مرفقيك.','أنزل الدمبل ببطء إلى مستوى الكتف مع الحفاظ على التحكم والشد.'], ARRAY['Sit on a bench with back support or stand with your feet hip-width apart. Hold a dumbbell in each hand at shoulder height with palms facing forward or slightly inward.','Engage your core, keep your spine neutral, and retract your shoulder blades lightly.','Press the dumbbells upward and slightly inward until your arms are fully extended without locking out at the elbows.','Slowly lower the dumbbells back to shoulder height while maintaining control and tension.'], ARRAY['anterior deltoid'], ARRAY['lateral deltoid','supraspinatus','triceps','trapezius','serratus anterior','pectoralis major clavicular','levator scapulae','biceps brachii'], NULL),
  ('تدوير الذراعين', 'Arm Circles', 'shoulders', 'none', 'قف بشكل مستقيم وقدماك بعرض الوركين، وذراعاك مفرودتان للجانبين عند مستوى الكتف. شد جذعك وحافظ على عمودك الفقري محايدًا. ابدأ برسم دوائر صغيرة للأمام بذراعيك، مع زيادة حجمها تدريجيًا. نفّذ الحركة لمدة 20-30 ثانية، ثم اعكس الاتجاه لنفس المدة.', 'Stand tall with feet hip-width apart, arms extended out to your sides at shoulder height. Engage your core and keep your spine neutral. Begin making small forward circles with your arms, gradually increasing the size. Perform for 20-30 seconds, then reverse direction for the same duration.', 'https://fitnessprogramer.com/wp-content/uploads/2021/07/Arm-Circles_Shoulders.gif', ARRAY['قف بشكل مستقيم وقدماك بعرض الوركين، وذراعاك مفرودتان للجانبين عند مستوى الكتف.','شد جذعك وحافظ على عمودك الفقري محايدًا للحفاظ على وضعية جيدة.','ابدأ برسم دوائر صغيرة للأمام بذراعيك، مع زيادة حجمها تدريجيًا.','نفّذ الحركة لمدة 20-30 ثانية، ثم اعكس الاتجاه لنفس المدة.','أنزل ذراعيك وهزهما بعد إكمال كلا الاتجاهين.'], ARRAY['Stand tall with feet hip-width apart, arms extended out to your sides at shoulder height.','Engage your core and keep your spine neutral to maintain good posture.','Begin making small forward circles with your arms, gradually increasing the size.','Perform for 20-30 seconds, then reverse the direction for the same duration.','Lower your arms and shake them out after completing both directions.'], ARRAY['shoulders'], ARRAY['trapezius','levator scapulae','pectoralis','triceps','rotator cuff','splenius'], 'beginner'),
  ('ضغط الدفع بالدمبل', 'Dumbbell Push Press', 'full_body', 'dumbbell', 'قف وقدماك بعرض الكتفين، وأمسك دمبل بكل يد مع ثني ذراعيك بزاوية 90 درجة وراحتا يديك متقابلتان. اثنِ ركبتيك قليلًا لبدء انخفاض خفيف، ثم ادفع للأعلى بانفجارية باستخدام رجليك بينما تضغط بالدمبل مباشرة فوق رأسك مع فرد ذراعيك بالكامل. أنزل الدمبل إلى وضع البداية بثني مرفقيك بتحكم.', 'Stand with feet shoulder-width apart, holding a dumbbell in each hand with arms bent at 90 degrees, palms facing each other. Bend your knees slightly for a small dip, then explosively push up with your legs while pressing the dumbbells straight overhead, extending your arms fully. Lower the dumbbells back to the starting position by bending your elbows with control.', 'https://fitnessprogramer.com/wp-content/uploads/2023/10/Dumbbell-Push-Press.gif', ARRAY['قف وقدماك بعرض الكتفين. أمسك دمبل بكل يد، مع ثني ذراعيك بزاوية 90 درجة، وراحتا يديك متقابلتان.','ابدأ الحركة بثني ركبتيك قليلًا لبدء انخفاض خفيف.','ادفع للأعلى بانفجارية باستخدام رجليك، وفي نفس الوقت اضغط بالدمبل مباشرة فوق كتفيك مع فرد ذراعيك بالكامل.','في أعلى الحركة يجب أن تكون ذراعاك مفرودتين تمامًا فوق رأسك، وراحتا يديك ما زالتا متقابلتين.','أنزل الدمبل إلى وضع البداية بثني مرفقيك والتحكم في النزول.','نفّذ العدد المطلوب من التكرارات حسب هدفك التدريبي.'], ARRAY['Stand with your feet shoulder-width apart. Hold a dumbbell in each hand, with your arms bent at a 90-degree angle, and your palms facing each other.','Begin the movement by slightly bending your knees, initiating a small dip.','Explosively push up with your legs. Simultaneously, press the dumbbells straight over your shoulders, extending your arms fully.','At the top of the movement, your arms should be fully extended overhead, palms still facing each other.','Lower the dumbbells back to the starting position by bending your elbows and controlling the descent.','Perform the desired number of repetitions, typically within a specific rep range based on your fitness goals.'], ARRAY['full body','anterior deltoid'], ARRAY['pectoralis major clavicular','trapezius','triceps','serratus anterior','quadriceps','hamstrings','calves','forearms','biceps','erector spinae','rectus abdominis'], NULL),
  ('رفع الذراع الجانبي', 'Side Arm Raise (Lateral Raise)', 'shoulders', 'none', 'قف وذراعاك بجانب جسمك، مع استقامة ظهرك وذراعيك. ارفع ذراعيك للجانبين حتى مستوى الكتف، مع الزفير أثناء الرفع والشهيق أثناء الإنزال. عد وكرر.', 'Stand with your arms at your sides, back and arms straight. Raise your arms to your sides at shoulder height, exhaling as you raise and inhaling as you lower. Return and repeat.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/arm-circles.gif', ARRAY['قف وذراعاك بجانب جسمك.','حافظ على استقامة ظهرك وذراعيك.','ارفع ذراعيك للجانبين حتى مستوى الكتف.','ازفر وأنت ترفع ذراعيك، واشهق وأنت تنزلهما.','عد وكرر.'], ARRAY['Stand with your arms at your sides.','Keep your back and arms straight.','Raise your arms to your sides at shoulder height.','Exhale as you raise your arms, and inhale as you lower them.','Return and repeat.'], ARRAY['lateral deltoid'], ARRAY['supraspinatus','serratus anterior','anterior deltoid','trapezius'], NULL),
  ('ضغط الكتف بجهاز سميث', 'Smith Machine Shoulder Press', 'shoulders', 'machine', 'ضع بنشًا للجلوس داخل جهاز سميث واضبط ارتفاع البار. أمسك البار مع ثني مرفقيك بزاوية 90 درجة تقريبًا عند مستوى الذقن. ازفر واضغط بالبار فوق رأسك، وحافظ على الوضع للحظة في الأعلى، ثم أنزله ببطء وبتحكم إلى وضع البداية.', 'Position a seated bench in the Smith Machine and adjust the barbell height. Grip the bar with elbows bent approximately 90 degrees at chin level. Exhale and press the barbell overhead, hold briefly at the top, then slowly lower back to the starting position.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Smith-Machine-Shoulder-Press.gif', ARRAY['ضع بنشًا للجلوس داخل جهاز سميث واضبط ارتفاع البار بحيث يسهل الوصول إليه.','أمسك البار مع ثني مرفقيك بزاوية 90 درجة تقريبًا عندما يصل البار لمستوى الذقن.','ازفر واضغط بالبار فوق رأسك.','حافظ على الوضع للحظة في الأعلى.','أنزل البار ببطء وبتحكم إلى وضع البداية.'], ARRAY['Position a seated bench in the Smith Machine and adjust the barbell height for easy access.','Grip the bar with elbows bent approximately 90 degrees when the bar reaches chin level.','Exhale and press the barbell over your head.','Hold briefly at the top position.','Slowly lower the bar back to the starting position in a controlled manner.'], ARRAY['anterior deltoid'], ARRAY['triceps','pectoralis major clavicular','lateral deltoid','trapezius','serratus anterior','levator scapulae','biceps brachii'], NULL),
  ('هز الكتف بالبار فوق الرأس', 'Barbell Overhead Shrug', 'shoulders', 'barbell', 'قف بشكل مستقيم وقدماك بعرض الكتفين تقريبًا. أمسك البار بقبضة مقلوبة، يداك أوسع قليلًا من عرض الكتفين. ارفع البار فوق رأسك مع فرد ذراعيك بالكامل. مع الحفاظ على ذراعيك مفرودتين وكتفيك للأسفل، اهز كتفيك للأعلى نحو أذنيك، مفعلًا عضلات الظهر العلوي والكتف. حافظ على وضع الأعلى لثانية أو اثنتين، ثم أنزل كتفيك بتحكم.', 'Stand straight with feet about shoulder-width apart. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Lift the barbell overhead, fully extending your arms. Keeping your arms straight and shoulders down, shrug your shoulders up toward your ears, engaging the upper back and shoulder muscles. Hold the top position for a second or two, then lower back down with control.', 'https://fitnessprogramer.com/wp-content/uploads/2022/07/overhead-shrug.gif', ARRAY['قف بشكل مستقيم وقدماك بعرض الكتفين تقريبًا. أمسك البار بقبضة مقلوبة، يداك أوسع قليلًا من عرض الكتفين. ارفع البار فوق رأسك مع فرد ذراعيك بالكامل والحفاظ على البار مباشرة فوق رأسك.','مع الحفاظ على ذراعيك مفرودتين وكتفيك للأسفل، اهز كتفيك للأعلى نحو أذنيك. ركز على تفعيل عضلات الظهر العلوي والكتف، ورفع لوحي الكتف بينما تضغط بالوزن فوق رأسك.','حافظ على وضع الأعلى لثانية أو اثنتين، ثم أنزل كتفيك إلى وضع البداية. احرص على استقامة ظهرك وشد جذعك طوال الحركة.'], ARRAY['Stand straight with feet about shoulder-width apart. Hold the barbell with an overhand grip, hands slightly wider than shoulder-width apart. Lift the barbell overhead, fully extending your arms and keeping the bar directly above your head.','Keeping your arms straight and your shoulders down, shrug your shoulders up toward your ears. Focus on engaging the upper back and shoulder muscles, and lift or elevate your scapula while you are pressing the weight overhead.','Hold the top position for a second or two, then lower your shoulders back down to the starting position. Make sure to keep your back straight and your core engaged throughout the movement.'], ARRAY['trapezius'], ARRAY['levator scapulae','rhomboids','anterior deltoid','lateral deltoid','erector spinae'], NULL),
  ('سحب دمبل على بنش مائل 45 درجة', '45 Degree Incline Dumbbell Row', 'back', 'dumbbell', 'اضبط بنشًا مائلًا بزاوية 45 درجة. استلق على وجهك على البنش مع الضغط بصدرك عليه بثبات. أمسك الدمبل بذراعين مفرودتين تحت الكتفين مباشرة، وراحتا يديك متجهتان للداخل. اسحب الدمبل للأعلى، مع ثني مرفقيك وسحب لوحي الكتف للخلف. أنزل الدمبل ببطء إلى الوضع الأصلي. أكمل 8-12 تكرارًا متحكمًا به لكل مجموعة.', 'Adjust an incline bench to a 45-degree angle. Lie face down on the bench with your chest firmly pressed against it. Hold dumbbells with arms extended directly below shoulders, palms facing inward. Pull the dumbbells upward, bending your elbows and retracting your shoulder blades. Slowly lower the dumbbells back to the initial position. Complete 8-12 controlled repetitions per set.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/45-Degree-Incline-Row.gif', ARRAY['اضبط بنشًا مائلًا بزاوية 45 درجة. استلق على وجهك على البنش مع الضغط بصدرك عليه بثبات.','أمسك الدمبل بذراعين مفرودتين تحت الكتفين مباشرة، وراحتا يديك متجهتان للداخل.','اسحب الدمبل للأعلى، مع ثني مرفقيك وسحب لوحي الكتف للخلف، حتى يتماشى المرفقان مع جذعك أو أعلى قليلًا.','أنزل الدمبل ببطء إلى الوضع الأصلي، مع فرد ذراعيك بالكامل دون تحرير شد الكتف.','أكمل 8-12 تكرارًا متحكمًا به لكل مجموعة.'], ARRAY['Adjust an incline bench to a 45-degree angle. Lie face down on the bench with your chest firmly pressed against it.','Hold dumbbells with arms extended directly below shoulders, palms facing inward.','Pull the dumbbells upward, bending your elbows and retracting your shoulder blades, lifting until elbows align with your torso or slightly higher.','Slowly lower the dumbbells back to the initial position, fully extending your arms without releasing shoulder tension.','Complete 8-12 controlled repetitions per set.'], ARRAY['shoulders','trapezius'], ARRAY['lateral deltoid','rhomboids','infraspinatus','teres minor','latissimus dorsi','brachioradialis','brachialis'], NULL),
  ('هز الكتف بالدمبل', 'Dumbbell Shrug', 'shoulders', 'dumbbell', 'قف وقدماك بعرض الكتفين، وحافظ على استقامة ظهرك. أمسك دمبل بكل يد وراحتا يديك متجهتان نحو جسمك. ارفع كتفيك ببطء بشكل مستقيم نحو أذنيك بأقصى ما يمكن. حافظ على وضع الأعلى للحظة لتحقيق أقصى انقباض للترابيزيوس. أنزل الدمبل ببطء إلى وضع البداية. كرر لمدة 3-4 مجموعات من 10-15 تكرارًا.', 'Stand with your feet shoulder-width apart, and keep your back straight. Hold a dumbbell in each hand with your palms facing your body. Slowly lift your shoulders straight up towards your ears as high as possible. Hold the top position momentarily to fully contract the traps. Slowly lower the dumbbells back down to the starting position. Repeat for 3-4 sets of 10-15 reps.', 'https://fitnessprogramer.com/wp-content/uploads/2021/04/Dumbbell-Shrug.gif', ARRAY['قف وقدماك بعرض الكتفين، وحافظ على استقامة ظهرك.','أمسك دمبل بكل يد وراحتا يديك متجهتان نحو جسمك.','ارفع كتفيك ببطء بشكل مستقيم نحو أذنيك بأقصى ما يمكن.','حافظ على وضع الأعلى للحظة لتحقيق أقصى انقباض للترابيزيوس.','أنزل الدمبل ببطء إلى وضع البداية.','كرر لمدة 3-4 مجموعات من 10-15 تكرارًا.'], ARRAY['Stand with your feet shoulder-width apart, and keep your back straight.','Hold a dumbbell in each hand with your palms facing your body.','Slowly lift your shoulders straight up towards your ears as high as possible.','Hold the top position momentarily to fully contract the traps.','Slowly lower the dumbbells back down to the starting position.','Repeat for 3-4 sets of 10-15 reps.'], ARRAY['trapezius upper'], ARRAY['levator scapulae','trapezius middle','lateral deltoid','erector spinae'], NULL),
  ('هز الكتف بالكابل', 'Cable Shrug', 'shoulders', 'cable', 'قف مواجهًا لبكرة كابل منخفضة مع مقبض مستقيم أو على شكل V. أمسك المقبض بقبضة مقلوبة وقف بشكل مستقيم مع ذراعيك مفرودتين للأسفل. اهز كتفيك بشكل مستقيم للأعلى نحو أذنيك مع الحفاظ على استقامة ذراعيك. حافظ على الوضع لحظة في الأعلى، ثم أنزل بتحكم وكرر. تمرين معزول يقوّي عضلات الترابيزيوس ويحسّن دعم وضعية الجسم.', 'Stand facing a low cable pulley attachment with a straight or V-bar handle. Grip the handle with an overhand grip and stand tall with arms extended down. Shrug your shoulders straight up toward your ears, keeping arms straight. Hold briefly at the top, then lower with control and repeat. This is an isolated exercise that develops the trapezius muscles and improves postural support.', 'https://fitnessprogramer.com/wp-content/uploads/2021/04/Cable-Shrug.gif', ARRAY['قف مواجهًا لبكرة كابل منخفضة مع مقبض مستقيم أو على شكل V.','أمسك المقبض بقبضة مقلوبة وقف بشكل مستقيم مع ذراعيك مفرودتين للأسفل.','اهز كتفيك بشكل مستقيم للأعلى نحو أذنيك مع الحفاظ على استقامة ذراعيك.','حافظ على الوضع لحظة في الأعلى، ثم أنزل بتحكم وكرر.'], ARRAY['Stand facing a low cable pulley attachment with a straight or V-bar handle.','Grip the handle with an overhand grip and stand tall with arms extended down.','Shrug your shoulders straight up toward your ears, keeping arms straight.','Hold briefly at the top, then lower with control and repeat.'], ARRAY['trapezius'], ARRAY['levator scapulae','erector spinae'], NULL),
  ('هز الكتف بالبار', 'Barbell Shrug', 'shoulders', 'barbell', 'قف وأنت تمسك البار أمام فخذيك بقبضة مقلوبة، وقدماك بعرض الكتفين. مع الحفاظ على استقامة ذراعيك، اهز كتفيك بشكل مستقيم للأعلى نحو أذنيك بأقصى ما يمكن. حافظ على وضع الأعلى للحظة، مع الضغط على عضلات الترابيزيوس. أنزل البار ببطء إلى وضع البداية وكرر. يُعد هز الكتف بالبار من أكثر التمارين فعالية لتقوية الترابيزيوس.', 'Stand holding a barbell in front of your thighs with an overhand grip, feet shoulder-width apart. Keeping your arms straight, shrug your shoulders straight up toward your ears as high as possible. Hold the top position briefly, squeezing the traps. Slowly lower the barbell back to the starting position and repeat. The barbell shrug is one of the most effective exercises for developing trapezius strength.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Barbell-Shrug.gif', ARRAY['قف وأنت تمسك البار أمام فخذيك بقبضة مقلوبة، وقدماك بعرض الكتفين.','مع الحفاظ على استقامة ذراعيك، اهز كتفيك بشكل مستقيم للأعلى نحو أذنيك بأقصى ما يمكن.','حافظ على وضع الأعلى للحظة، مع الضغط على عضلات الترابيزيوس.','أنزل البار ببطء إلى وضع البداية وكرر.'], ARRAY['Stand holding a barbell in front of your thighs with an overhand grip, feet shoulder-width apart.','Keeping your arms straight, shrug your shoulders straight up toward your ears as high as possible.','Hold the top position briefly, squeezing the traps.','Slowly lower the barbell back to the starting position and repeat.'], ARRAY['trapezius'], ARRAY['levator scapulae','trapezius middle','erector spinae'], NULL),
  ('هز الكتف بالبار من الخلف', 'Behind The Back Barbell Shrug', 'shoulders', 'barbell', 'قف وقدماك بعرض الكتفين، وأمسك البار خلف ظهرك بقبضة مقلوبة. اهز كتفيك بشكل مستقيم للأعلى بأقصى ما يمكن مع الحفاظ على استقامة ذراعيك. حافظ على الوضع لحظة في الأعلى، ثم أنزل بتحكم وكرر.', 'Stand with your feet shoulder-width apart, holding a barbell behind your back with a pronated grip. Shrug your shoulders straight up as high as possible, keeping your arms straight. Hold briefly at the top, then lower with control and repeat.', 'https://fitnessprogramer.com/wp-content/uploads/2023/03/Behind-The-Back-Barbell-Shrug-Reverse-Barbell-Shrug.gif', ARRAY['قف وقدماك بعرض الكتفين، وأمسك البار خلف ظهرك بقبضة مقلوبة (راحتا يديك تجاه الخلف).','اهز كتفيك بشكل مستقيم للأعلى بأقصى ما يمكن مع الحفاظ على استقامة ذراعيك.','حافظ على الوضع لحظة في الأعلى، ثم أنزل بتحكم وكرر.'], ARRAY['Stand with your feet shoulder-width apart, holding a barbell behind your back with a pronated grip (palms facing back).','Shrug your shoulders straight up as high as possible, keeping your arms straight.','Hold briefly at the top, then lower with control and repeat.'], ARRAY['trapezius'], ARRAY[]::text[], NULL),
  ('هز الكتف بالدمبل على بنش مائل', 'Dumbbell Incline Shrug', 'shoulders', 'dumbbell', 'استلق على وجهك على بنش مائل، وأمسك دمبل بكل يد مع ترك ذراعيك تتدلى للأسفل. اهز كتفيك بشكل مستقيم للأعلى نحو أذنيك مع الحفاظ على استقامة ذراعيك. حافظ على الوضع لحظة في الأعلى، ثم أنزل بتحكم وكرر. يساعد تقوية الترابيزيوس على تثبيت الرقبة والظهر وتقليل التوتر.', 'Lie face down on an incline bench holding a dumbbell in each hand, arms hanging straight down. Shrug your shoulders straight up toward your ears, keeping arms straight. Hold briefly at the top, then lower with control and repeat. Strengthening the trapezius helps stabilize the neck and back and reduce tension.', 'https://fitnessprogramer.com/wp-content/uploads/2021/04/Dumbbell-Incline-Shrug.gif', ARRAY['استلق على وجهك على بنش مائل، وأمسك دمبل بكل يد مع ترك ذراعيك تتدلى للأسفل.','اهز كتفيك بشكل مستقيم للأعلى نحو أذنيك مع الحفاظ على استقامة ذراعيك.','حافظ على الوضع لحظة في الأعلى، ثم أنزل بتحكم وكرر.'], ARRAY['Lie face down on an incline bench holding a dumbbell in each hand, arms hanging straight down.','Shrug your shoulders straight up toward your ears, keeping arms straight.','Hold briefly at the top, then lower with control and repeat.'], ARRAY['trapezius'], ARRAY['levator scapulae','erector spinae'], NULL),
  ('سحب الحبل للوجه', 'Face Pull', 'shoulders', 'cable', 'ثبّت مقبض الحبل على جهاز كابل عند مستوى الصدر أو العين. أمسك المقابض بقبضة مقلوبة، وراحتا يديك متجهتان للأسفل. قف بشكل مستقيم وقدماك بعرض الكتفين، مع شد جذعك. اسحب الحبل نحو وجهك، مع فتح مرفقيك للخارج، واضغط بلوحي كتفك معًا عند القمة. عد ببطء إلى وضع البداية.', 'Attach a rope handle to a cable machine at chest or eye level. Hold the handles with an overhand grip, palms facing down. Stand tall with feet shoulder-width apart, engaging your core. Pull the rope toward your face, elbows flaring outward, and squeeze your shoulder blades together at the peak. Slowly return to the starting position.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Face-Pull.gif', ARRAY['ثبّت مقبض الحبل على جهاز كابل أو استخدم أشرطة مطاطية عند مستوى الصدر أو العين.','أمسك المقابض بقبضة مقلوبة، وراحتا يديك متجهتان للأسفل.','قف بشكل مستقيم وقدماك بعرض الكتفين، مع شد جذعك.','اسحب الحبل نحو وجهك، مع فتح مرفقيك للخارج.','اضغط بلوحي كتفك معًا عند قمة الحركة.','عد ببطء إلى وضع البداية.'], ARRAY['Attach a rope handle to a cable machine or use resistance bands at chest or eye level.','Hold the handles with an overhand grip, palms facing down.','Stand tall with feet shoulder-width apart, engaging your core.','Pull the rope toward your face, elbows flaring outward.','Squeeze your shoulder blades together at the peak of the movement.','Slowly return to the starting position.'], ARRAY['shoulders','trapezius'], ARRAY['infraspinatus','teres minor','lateral deltoid','brachioradialis','brachialis','rhomboids'], NULL),
  ('فتح الشريط المطاطي للخارج', 'Band Pull-Apart', 'shoulders', 'band', 'أمسك نهايتي الشريط المطاطي بكلتا يديك. قف وقدماك بعرض الكتفين تقريبًا، مواجهًا الجسم الثابت، وراحتا يديك متقابلتين وذراعاك موازيتان للأرض. ازفر وحرّك يديك بعيدًا عن بعضهما بحيث تنفتح ذراعاك للجانبين. حافظ على الوضع واضغط بلوحي كتفك معًا قبل العودة ببطء إلى وضع البداية.', 'Grab the ends of the resistance band with both hands. Stand with your feet shoulder-width apart, facing the secured object, palms facing each other and arms parallel to the floor. Exhale and move your hands apart so your arms go out to the sides. Briefly hold and squeeze your shoulder blades together before slowly returning to the starting position.', 'https://fitnessprogramer.com/wp-content/uploads/2021/06/Band-pull-apart.gif', ARRAY['أمسك نهايتي الشريط المطاطي بكلتا يديك. قف وقدماك بعرض الكتفين تقريبًا، مواجهًا الجسم الثابت.','حافظ على أن تكون راحتا يديك متقابلتين وذراعاك موازيتان للأرض في وضع البداية.','ازفر وحرّك يديك بعيدًا عن بعضهما بحيث تنفتح ذراعاك للجانبين.','حافظ على الوضع لثانية واضغط بلوحي كتفك معًا قبل العودة ببطء إلى وضع البداية.'], ARRAY['Grab the ends of the resistance band with both hands. Stand with your feet about shoulder''s width apart, and face the secured object.','Keep your palms facing each other and your arms parallel to the floor as your starting position.','Exhale and move your hands apart so that your arms go out to the sides.','Briefly hold for a second and squeeze your shoulder blades together before slowly returning to the starting position.'], ARRAY['shoulders','trapezius'], ARRAY['infraspinatus','teres minor','lateral deltoid','rhomboids'], NULL),
  ('سحب البار العمودي', 'Barbell Upright Row', 'shoulders', 'barbell', 'ابدأ بالإمساك بالبار وراحتا يديك متجهتان نحو جسمك، مع تقريب يديك من بعضهما أكثر من عرض الكتفين. ازفر وارفع مرفقيك وكتفيك حتى زاوية 90 درجة تقريبًا. حافظ على الوضع للحظة قصيرة ثم أنزل ببطء إلى وضع البداية.', 'Begin by grabbing the barbell with your palms facing your body, hands closer together than shoulder width. Exhale and raise your elbows and shoulders up to about 90 degrees. Hold briefly then slowly lower to the starting position.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/barbell-uprightrow.gif', ARRAY['ابدأ بالإمساك بالبار وراحتا يديك متجهتان نحو جسمك، مع تقريب يديك من بعضهما أكثر من عرض الكتفين.','ازفر وارفع مرفقيك وكتفيك حتى زاوية 90 درجة تقريبًا.','حافظ على الوضع للحظة قصيرة ثم أنزل ببطء إلى وضع البداية.'], ARRAY['Begin by grabbing the barbell with your palms facing your body. Place your hands fairly close together, closer than shoulder width.','Exhale and raise your elbows and shoulders up to about 90 degrees.','Hold just for a brief second and then slowly lower to the starting position.'], ARRAY['shoulders','trapezius'], ARRAY['lateral deltoid','supraspinatus','anterior deltoid','infraspinatus','teres minor','brachialis','brachioradialis','biceps','serratus anterior','levator scapulae'], NULL),
  ('سحب الدمبل العمودي', 'Dumbbell Upright Row', 'shoulders', 'dumbbell', 'قف وأنت تمسك دمبل بكل يد أمام فخذيك، وراحتا يديك متجهتان نحو جسمك. ازفر وارفع مرفقيك والدمبل نحو ذقنك، مع قيادة الحركة بمرفقيك. حافظ على الوضع للحظة في الأعلى، ثم أنزل ببطء إلى وضع البداية. يركز هذا التمرين على عضلات الترابيزيوس والكتف.', 'Stand holding a dumbbell in each hand in front of your thighs, palms facing your body. Exhale and raise your elbows and the dumbbells up toward your chin, leading with your elbows. Hold briefly at the top, then slowly lower to the starting position. This exercise focuses on the trapezius and shoulder muscles.', 'https://fitnessprogramer.com/wp-content/uploads/2021/04/Dumbbell-Upright-Row.gif', ARRAY['قف وأنت تمسك دمبل بكل يد أمام فخذيك، وراحتا يديك متجهتان نحو جسمك.','ازفر وارفع مرفقيك والدمبل نحو ذقنك، مع قيادة الحركة بمرفقيك.','حافظ على الوضع للحظة في الأعلى، ثم أنزل ببطء إلى وضع البداية.'], ARRAY['Stand holding a dumbbell in each hand in front of your thighs, palms facing your body.','Exhale and raise your elbows and the dumbbells up toward your chin, leading with your elbows.','Hold briefly at the top, then slowly lower to the starting position.'], ARRAY['shoulders','trapezius'], ARRAY['supraspinatus','anterior deltoid','infraspinatus','teres minor','brachialis','brachioradialis','biceps','serratus anterior','levator scapulae'], NULL),
  ('فتح الكتف الخلفي بالكابل', 'Cable Rear Delt Fly', 'shoulders', 'cable', 'اضبط أذرع الكابل عند مستوى الكتف. أمسك الكابل الأيسر بيدك اليمنى، وتقاطع ذراعيك بالإمساك بالكابل الأيمن بيدك اليسرى. ازفر وبينما تحافظ على استقامة ذراعيك اسحب كتفيك للخارج نحو الجانبين. حافظ على الوضع للحظة، ثم عد ببطء إلى وضع البداية.', 'Position cable arms at shoulder height. Grab left cable with right hand and overlap arms by grabbing right cable with left hand. Exhale and, keeping your arms straight, pull your shoulders out to the sides. Hold briefly, then slowly return to the starting position.', NULL, ARRAY['اضبط أذرع الكابل عند مستوى الكتف.','أمسك الكابل الأيسر بيدك اليمنى، وتقاطع ذراعيك بالإمساك بالكابل الأيمن بيدك اليسرى.','ازفر وبينما تحافظ على استقامة ذراعيك اسحب كتفيك للخارج نحو الجانبين.','حافظ على الوضع للحظة، ثم عد ببطء إلى وضع البداية.'], ARRAY['Position cable arms at shoulder height.','Grab left cable with right hand and overlap arms by grabbing right cable with left hand.','Exhale and while keeping your arms straight pull your shoulders out to the sides.','Hold briefly, then slowly return to starting position.'], ARRAY['shoulders','trapezius'], ARRAY['infraspinatus','teres minor','lateral deltoid','rhomboids'], NULL),
  ('رفرفة الكتف الخلفي منحنيًا', 'Bent Over Lateral Raise', 'shoulders', 'dumbbell', 'انحنِ للأمام من الوركين مع الحفاظ على استقامة أسفل ظهرك وأنت تمسك الدمبل، ومرفقاك مثنيان قليلًا. ازفر وارفع ذراعيك للجانبين. حافظ على الوضع للحظة قصيرة ثم أنزل ببطء إلى وضع البداية.', 'Bend forward from the hips and keep your lower back straight while holding dumbbells, with elbows slightly bent. Exhale and raise your arms out to the sides. Hold for a brief second and then slowly lower to the starting position.', 'https://fitnessprogramer.com/wp-content/uploads/2021/02/Bent-Over-Lateral-Raise.gif', ARRAY['انحنِ للأمام من الوركين مع الحفاظ على استقامة أسفل ظهرك وأنت تمسك الدمبل.','حافظ على ثني مرفقيك قليلًا.','ازفر وارفع ذراعيك للجانبين.','حافظ على الوضع للحظة قصيرة ثم أنزل ببطء إلى وضع البداية.'], ARRAY['Bend forward from the hips and keep your lower back straight while holding dumbbells.','Keep your elbows slightly bent.','Exhale and raise your arms out to the sides.','Hold for a brief second and then slowly lower to the starting position.'], ARRAY['shoulders','trapezius'], ARRAY['infraspinatus','teres minor','lateral deltoid','rhomboids'], NULL);
